const ROOT = process.cwd(), P = (r) => path.join(ROOT, r);
const FILES = [{"path": "lib/play.ts", "require": "install-play.js", "src": "", "sig": "", "drop": [], "skipIf": []}, {"path": "components/report/ReportView.tsx", "src": "\"use client\";\n\nimport { useEffect, useMemo, useRef, useState, type ReactNode } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ClipboardCheck, Crown, X, Check, Flag, Clock, ShieldCheck, Ban, Swords, Map as MapIcon, Calendar, Link2, LogIn, Info, Loader2,\n  ArrowLeftRight, Search, Zap, RotateCcw, Skull, FileText, ChevronRight,\n} from \"lucide-react\";\nimport { createClient } from \"@/lib/supabase/client\";\nimport { C } from \"@/lib/theme\";\nimport { useLanguage } from \"@/lib/i18n/LanguageContext\";\nimport { useFeedback } from \"@/components/FeedbackProvider\";\nimport { maps as MAP_FILES } from \"@/lib/maps-data\";\nimport GeneralSelect from \"@/components/GeneralSelect\";\nimport { readGenerals, generalShort, type GeneralKey } from \"@/lib/generals\";\n\ntype Mode = \"2v2\" | \"3v3\" | \"4v4\" | \"ffa\";\ntype Sub = {\n  id: string; created_at: string; submitter_username: string; mode: Mode; participants: string[]; winners: string[];\n  map: string | null; notes: string | null; replay_url: string | null; generals: unknown; match_date: string;\n  status: \"pending\" | \"confirmed\" | \"disputed\" | \"approved\" | \"rejected\"; confirmed_by: string | null; dispute_reason: string | null;\n};\ntype Person = { username: string; avatar: string | null; rating: number };\ntype QuickFill = { key: string; kind: \"challenge\" | \"rematch\"; label: string; sub: string; mode: Mode; mine: string[]; opps: string[]; ffa: string[] };\n\nconst WRAP = \"mx-auto max-w-[1180px] px-5 md:px-10\";\nconst RED = \"#DC2626\";\nconst LOSS = \"#F87171\";\nconst MODES: Mode[] = [\"2v2\", \"3v3\", \"4v4\", \"ffa\"];\nconst SIZE: Record<Mode, number> = { \"2v2\": 2, \"3v3\": 3, \"4v4\": 4, ffa: 8 };\n\nconst TIERS: [number, { en: string; ar: string }][] = [\n  [-Infinity, { en: \"Private\", ar: \"جندي\" }], [900, { en: \"Corporal\", ar: \"عريف\" }], [1000, { en: \"Sergeant\", ar: \"رقيب\" }], [1100, { en: \"Lieutenant\", ar: \"ملازم\" }],\n  [1200, { en: \"Captain\", ar: \"نقيب\" }], [1300, { en: \"Major\", ar: \"رائد\" }], [1400, { en: \"Colonel\", ar: \"عقيد\" }], [1500, { en: \"Brigadier General\", ar: \"عميد\" }],\n  [1600, { en: \"General\", ar: \"لواء\" }], [1700, { en: \"Commander\", ar: \"قائد\" }],\n];\nconst tierOf = (r: number) => TIERS.reduce((acc, [min, t]) => (r >= min ? t : acc), TIERS[0][1]);\n\n// Arabic needs a native review.\nconst TEXT = {\n  en: {\n    eyebrow: \"Field report\", title: \"Report a result\", sub: \"Played a ranked match? File the report — the other side confirms, an admin approves, and ratings update automatically.\",\n    steps: [\"Report\", \"Opponent confirms\", \"Admin approves\"],\n    signIn: \"Sign in to report a result.\", login: \"Log in\", banned: \"Banned accounts can't report results.\",\n    notReady: \"Result reporting isn't switched on yet — an admin needs to run sql/match-submissions.sql once in Supabase.\",\n    quick: \"Quick fill\", quickSub: \"One click fills in the players.\", fromChallenge: \"Accepted challenge\", rematch: \"Rematch\", use: \"Use\",\n    oneVone: \"1v1 counts on the FFA ladder.\",\n    mode: \"Mode\", yourTeam: \"Your team\", opponents: \"Opponents\", players: \"Players\", search: \"Add player — type a name\", noMatch: \"No player found\",\n    move: \"Move to the other side\", remove: \"Remove\", winner: \"Winner\", result: \"Result\", victory: \"Victory\", defeat: \"Defeat\", victorySub: \"Your team won\", defeatSub: \"Your team lost\",\n    pickWinner: \"Tap the crown next to the winner.\",\n    details: \"Details\", mapLabel: \"Map\", date: \"Date\", replay: \"Replay link (optional)\", replayPh: \"Discord or Drive link\", notes: \"Notes (optional)\",\n    preview: \"Battle report\", defeated: \"defeated\", won: \"won the FFA against\", on: \"on\",\n    hint: { players: \"Add at least one player to each side.\", ffa: \"Add at least one other player.\", result: \"Choose Victory or Defeat.\", winner: \"Choose the winner.\", tooMany: (n: number) => `Max ${n} players per side in this mode.` },\n    submit: \"Send report\", sending: \"Sending…\", sent: \"Report sent — waiting for the other side to confirm.\",\n    needs: \"Waiting for your answer\", needsSub: \"Someone reported a match you played. Is it right?\", confirm: \"Confirm\", dispute: \"Dispute\",\n    disputeTitle: \"Dispute this result\", disputeMsg: \"Tell the admins what's wrong. They'll check the replay and decide.\", disputePh: \"e.g. we actually won, wrong players\",\n    yours: \"Your reports\", none: \"No reports yet.\", reportedBy: \"by\", vs: \"vs\",\n    st: { pending: \"Waiting for the other side\", confirmed: \"Confirmed — waiting for an admin\", disputed: \"Disputed — an admin will decide\", approved: \"Approved — on the ladder\", rejected: \"Rejected\" },\n    errUnknown: (n: string) => `\"${n}\" isn't a registered player.`, errDup: \"That player is already in this match.\",\n  },\n  ar: {\n    eyebrow: \"بلاغ ميداني\", title: \"الإبلاغ عن نتيجة\", sub: \"لعبت مباراة مصنّفة؟ قدّم البلاغ — يؤكده الطرف الآخر، يعتمده مشرف، ويتحدّث التقييم تلقائياً.\",\n    steps: [\"البلاغ\", \"تأكيد الخصم\", \"اعتماد المشرف\"],\n    signIn: \"سجّل الدخول للإبلاغ عن نتيجة.\", login: \"تسجيل الدخول\", banned: \"الحسابات المحظورة لا يمكنها الإبلاغ عن النتائج.\",\n    notReady: \"ميزة الإبلاغ غير مفعّلة بعد — يجب على أحد المشرفين تشغيل sql/match-submissions.sql مرة واحدة في Supabase.\",\n    quick: \"تعبئة سريعة\", quickSub: \"ضغطة واحدة تملأ اللاعبين.\", fromChallenge: \"تحدٍّ مقبول\", rematch: \"إعادة المباراة\", use: \"استخدم\",\n    oneVone: \"مباريات 1v1 تُحسب في تصنيف FFA.\",\n    mode: \"النمط\", yourTeam: \"فريقك\", opponents: \"الخصوم\", players: \"اللاعبون\", search: \"أضف لاعباً — اكتب اسماً\", noMatch: \"لا يوجد لاعب\",\n    move: \"انقل إلى الطرف الآخر\", remove: \"إزالة\", winner: \"الفائز\", result: \"النتيجة\", victory: \"انتصار\", defeat: \"هزيمة\", victorySub: \"فاز فريقك\", defeatSub: \"خسر فريقك\",\n    pickWinner: \"اضغط التاج بجانب الفائز.\",\n    details: \"التفاصيل\", mapLabel: \"الخريطة\", date: \"التاريخ\", replay: \"رابط الإعادة (اختياري)\", replayPh: \"رابط ديسكورد أو درايف\", notes: \"ملاحظات (اختياري)\",\n    preview: \"تقرير المعركة\", defeated: \"هزم\", won: \"فاز بـ FFA ضد\", on: \"على\",\n    hint: { players: \"أضف لاعباً واحداً على الأقل لكل طرف.\", ffa: \"أضف لاعباً آخر على الأقل.\", result: \"اختر انتصار أو هزيمة.\", winner: \"اختر الفائز.\", tooMany: (n: number) => `${n} لاعبين كحد أقصى لكل طرف في هذا النمط.` },\n    submit: \"إرسال البلاغ\", sending: \"جارٍ الإرسال…\", sent: \"تم إرسال البلاغ — بانتظار تأكيد الطرف الآخر.\",\n    needs: \"بانتظار ردّك\", needsSub: \"أبلغ أحدهم عن مباراة لعبتها. هل هي صحيحة؟\", confirm: \"تأكيد\", dispute: \"اعتراض\",\n    disputeTitle: \"الاعتراض على النتيجة\", disputeMsg: \"أخبر المشرفين بالخطأ وسيتحققون من الإعادة ويقررون.\", disputePh: \"مثال: نحن من فاز، لاعبون خاطئون\",\n    yours: \"بلاغاتك\", none: \"لا توجد بلاغات بعد.\", reportedBy: \"من\", vs: \"ضد\",\n    st: { pending: \"بانتظار الطرف الآخر\", confirmed: \"مؤكَّدة — بانتظار المشرف\", disputed: \"معترض عليها — سيقرر المشرف\", approved: \"معتمدة — في التصنيف\", rejected: \"مرفوضة\" },\n    errUnknown: (n: string) => `«${n}» ليس لاعباً مسجّلاً.`, errDup: \"هذا اللاعب موجود في المباراة بالفعل.\",\n  },\n};\n\nconst CSS = `\n@keyframes czr-in { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }\n@keyframes czr-pop { 0% { transform: scale(0.96); } 60% { transform: scale(1.02); } 100% { transform: none; } }\n.czr-in { animation: czr-in 0.5s cubic-bezier(0.2, 0.7, 0.2, 1) both; }\n.czr-pop { animation: czr-pop 0.3s ease both; }\n.czr-row { transition: background-color 0.2s ease, border-color 0.2s ease; }\n.czr-card { transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease; }\n.czr-card:hover { transform: translateY(-2px); }\n@media (prefers-reduced-motion: reduce) { .czr-in, .czr-pop { animation: none !important; } .czr-card:hover { transform: none; } }\n`;\n\nconst mono = { fontFamily: \"var(--font-mono), monospace\" } as const;\n\nfunction Brackets({ color = C.amberDim }: { color?: string }) {\n  const s = { width: 12, height: 12, borderColor: color } as const;\n  return (\n    <span aria-hidden=\"true\" className=\"pointer-events-none absolute inset-0\">\n      <span className=\"absolute left-0 top-0 border-l-2 border-t-2\" style={s} />\n      <span className=\"absolute right-0 top-0 border-r-2 border-t-2\" style={s} />\n      <span className=\"absolute bottom-0 left-0 border-b-2 border-l-2\" style={s} />\n      <span className=\"absolute bottom-0 right-0 border-b-2 border-r-2\" style={s} />\n    </span>\n  );\n}\n\nfunction Section({ code, title, icon: Icon, children, accent = C.amber, right }: { code: string; title: string; icon: typeof Swords; children: ReactNode; accent?: string; right?: ReactNode }) {\n  return (\n    <section className=\"czr-in relative border\" style={{ background: \"linear-gradient(180deg, #12150E, #0E110B)\", borderColor: C.line }}>\n      <Brackets />\n      <header className=\"flex items-center justify-between gap-3 border-b px-5 py-3\" style={{ borderColor: C.line }}>\n        <h2 className=\"flex items-center gap-2.5\">\n          <span className=\"text-[10px] tracking-[0.2em]\" style={{ color: C.muted, ...mono }}>{code}</span>\n          <Icon size={15} style={{ color: accent }} aria-hidden=\"true\" />\n          <span className=\"cz-display text-lg uppercase\" style={{ fontWeight: 700, letterSpacing: \"0.04em\" }}>{title}</span>\n        </h2>\n        {right}\n      </header>\n      <div className=\"p-5\">{children}</div>\n    </section>\n  );\n}\n\n// Type-ahead player search with avatars and ranks\nfunction PlayerPicker({ people, exclude, onPick, placeholder, noMatch, lang }: { people: Person[]; exclude: string[]; onPick: (n: string) => void; placeholder: string; noMatch: string; lang: \"en\" | \"ar\" }) {\n  const [q, setQ] = useState(\"\");\n  const [open, setOpen] = useState(false);\n  const [hi, setHi] = useState(0);\n  const box = useRef<HTMLDivElement>(null);\n  const list = useMemo(() => {\n    const t = q.trim().toLowerCase();\n    if (!t) return [];\n    return people.filter((p) => !exclude.includes(p.username) && p.username.toLowerCase().includes(t)).sort((a, b) => Number(!a.username.toLowerCase().startsWith(t)) - Number(!b.username.toLowerCase().startsWith(t)) || b.rating - a.rating).slice(0, 6);\n  }, [q, people, exclude]);\n  useEffect(() => {\n    const close = (e: MouseEvent) => box.current && !box.current.contains(e.target as Node) && setOpen(false);\n    document.addEventListener(\"mousedown\", close);\n    return () => document.removeEventListener(\"mousedown\", close);\n  }, []);\n  const pick = (n: string) => {\n    onPick(n);\n    setQ(\"\");\n    setOpen(false);\n    setHi(0);\n  };\n  return (\n    <div ref={box} className=\"relative\">\n      <Search size={15} aria-hidden=\"true\" className=\"pointer-events-none absolute top-1/2 -translate-y-1/2\" style={{ insetInlineStart: 12, color: C.muted }} />\n      <input\n        role=\"combobox\"\n        aria-expanded={open && q.trim().length > 0}\n        aria-label={placeholder}\n        value={q}\n        onChange={(e) => { setQ(e.target.value); setOpen(true); setHi(0); }}\n        onFocus={() => setOpen(true)}\n        onKeyDown={(e) => {\n          if (e.key === \"ArrowDown\") { e.preventDefault(); setHi((h) => Math.min(h + 1, list.length - 1)); }\n          if (e.key === \"ArrowUp\") { e.preventDefault(); setHi((h) => Math.max(h - 1, 0)); }\n          if (e.key === \"Enter\") { e.preventDefault(); if (list[hi]) pick(list[hi].username); }\n          if (e.key === \"Escape\") setOpen(false);\n        }}\n        placeholder={placeholder}\n        className=\"min-h-[44px] w-full border border-dashed border-[#3A4029] bg-[#0A0C08] pe-3 ps-9 text-sm text-[#EDEAE0] focus:border-solid focus:border-[#E8A63D]\"\n      />\n      {open && q.trim() && (\n        <ul role=\"listbox\" className=\"absolute inset-x-0 top-full z-20 mt-1 border\" style={{ background: \"#12150E\", borderColor: C.amberDim, boxShadow: \"0 14px 40px rgba(0,0,0,0.6)\" }}>\n          {list.length === 0 && <li className=\"px-3 py-3 text-sm\" style={{ color: C.muted }}>{noMatch}</li>}\n          {list.map((p, i) => (\n            <li key={p.username} role=\"option\" aria-selected={i === hi}>\n              <button type=\"button\" onMouseEnter={() => setHi(i)} onMouseDown={(e) => { e.preventDefault(); pick(p.username); }} className=\"flex w-full items-center gap-3 px-3 py-2 text-start\" style={{ background: i === hi ? \"#1C2114\" : \"transparent\" }}>\n                {/* eslint-disable-next-line @next/next/no-img-element */}\n                <img src={p.avatar || \"/default-avatar.svg\"} alt=\"\" className=\"h-7 w-7 rounded-full object-cover\" style={{ border: `1px solid ${C.lineStrong}` }} />\n                <span className=\"min-w-0 flex-1 truncate text-sm\" style={{ fontWeight: 600 }}>{p.username}</span>\n                <span className=\"text-[11px]\" style={{ color: C.amber, ...mono }}>{tierOf(p.rating)[lang]} · {p.rating}</span>\n              </button>\n            </li>\n          ))}\n        </ul>\n      )}\n    </div>\n  );\n}\n\nexport default function ReportView() {\n  const supabase = useMemo(() => createClient(), []);\n  const fb = useFeedback();\n  const { locale } = useLanguage();\n  const lang = locale === \"ar\" ? \"ar\" : \"en\";\n  const tx = TEXT[lang];\n\n  const [me, setMe] = useState<{ id: string; username: string; banned: boolean } | null | undefined>(undefined);\n  const [people, setPeople] = useState<Person[]>([]);\n  const [subs, setSubs] = useState<Sub[]>([]);\n  const [quick, setQuick] = useState<QuickFill[]>([]);\n  const [ready, setReady] = useState(true);\n  const [mode, setMode] = useState<Mode>(\"2v2\");\n  const [mates, setMates] = useState<string[]>([]);\n  const [opps, setOpps] = useState<string[]>([]);\n  const [ffa, setFfa] = useState<string[]>([]);\n  const [won, setWon] = useState<boolean | null>(null);\n  const [ffaWinner, setFfaWinner] = useState<string | null>(null);\n  const [generals, setGenerals] = useState<Record<string, GeneralKey | \"\">>({});\n  const [map, setMap] = useState(\"\");\n  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));\n  const [replay, setReplay] = useState(\"\");\n  const [notes, setNotes] = useState(\"\");\n  const [sending, setSending] = useState(false);\n  const [busy, setBusy] = useState<string | null>(null);\n  const [filled, setFilled] = useState<string | null>(null);\n  const [tried, setTried] = useState(false);\n\n  const byName = useMemo(() => Object.fromEntries(people.map((p) => [p.username, p])), [people]);\n\n  async function load(username: string, userId: string) {\n    const { data, error } = await supabase.from(\"match_submissions\").select(\"*\").order(\"created_at\", { ascending: false }).limit(200);\n    if (error) {\n      setReady(false);\n      return;\n    }\n    const mineSubs = ((data ?? []) as Sub[]).filter((s) => s.participants.includes(username));\n    setSubs(mineSubs);\n\n    // quick fill: accepted challenges (last 7 days) + recent rosters for a rematch\n    const q: QuickFill[] = [];\n    const since = new Date(Date.now() - 7 * 86400000).toISOString();\n    const { data: ch } = await supabase.from(\"challenges\").select(\"id, from_user, from_username, to_username, mode, status, responded_at\").eq(\"status\", \"accepted\").gte(\"responded_at\", since).order(\"responded_at\", { ascending: false }).limit(5);\n    for (const c of (ch ?? []) as { id: string; from_user: string; from_username: string; to_username: string; mode: string; responded_at: string }[]) {\n      const other = c.from_user === userId ? c.to_username : c.from_username;\n      const m: Mode = c.mode === \"1v1\" ? \"ffa\" : (c.mode as Mode);\n      q.push({ key: `c:${c.id}`, kind: \"challenge\", label: `${tx.vs} ${other}`, sub: c.mode.toUpperCase(), mode: m, mine: [], opps: m === \"ffa\" ? [] : [other], ffa: m === \"ffa\" ? [other] : [] });\n    }\n    const seen = new Set<string>();\n    for (const s of mineSubs.slice(0, 10)) {\n      const sig = `${s.mode}|${[...s.participants].sort().join(\",\")}`;\n      if (seen.has(sig) || q.filter((x) => x.kind === \"rematch\").length >= 3) continue;\n      seen.add(sig);\n      const mySide = s.winners.includes(username) ? s.winners : s.participants.filter((p) => !s.winners.includes(p));\n      const other = s.participants.filter((p) => !mySide.includes(p));\n      q.push({ key: `r:${s.id}`, kind: \"rematch\", label: s.mode === \"ffa\" ? s.participants.filter((p) => p !== username).join(\", \") : `${tx.vs} ${other.join(\" + \")}`, sub: s.mode.toUpperCase(), mode: s.mode, mine: mySide.filter((p) => p !== username), opps: s.mode === \"ffa\" ? [] : other, ffa: s.mode === \"ffa\" ? s.participants.filter((p) => p !== username) : [] });\n    }\n    setQuick(q);\n    return q;\n  }\n\n  useEffect(() => {\n    (async () => {\n      const { data: { user } } = await supabase.auth.getUser();\n      if (!user) return setMe(null);\n      const { data: p } = await supabase.from(\"profiles\").select(\"username, banned\").eq(\"id\", user.id).single();\n      if (!p?.username) return setMe(null);\n      setMe({ id: user.id, username: p.username, banned: !!p.banned });\n      const { data: all } = await supabase.from(\"profiles\").select(\"username, avatar_url, rating_team\").eq(\"banned\", false).order(\"username\");\n      setPeople(((all ?? []) as { username: string; avatar_url: string | null; rating_team: number | null }[]).map((x) => ({ username: x.username, avatar: x.avatar_url, rating: Math.round(Number(x.rating_team ?? 1000)) })));\n      const q = await load(p.username, user.id);\n      // /report?challenge=<id> fills the form straight from an accepted challenge\n      const wanted = new URLSearchParams(window.location.search).get(\"challenge\");\n      const hit = wanted && q?.find((x) => x.key === `c:${wanted}`);\n      if (hit) applyQuick(hit);\n    })();\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const size = SIZE[mode];\n  const team = mode !== \"ffa\";\n  const myTeam = me ? [me.username, ...mates] : mates;\n  const ffaPlayers = me ? [me.username, ...ffa] : ffa;\n  const everyone = team ? [...myTeam, ...opps] : ffaPlayers;\n\n  function applyQuick(q: QuickFill) {\n    setMode(q.mode);\n    setMates(q.mine.slice(0, SIZE[q.mode] - 1));\n    setOpps(q.opps.slice(0, SIZE[q.mode]));\n    setFfa(q.ffa);\n    setWon(null);\n    setFfaWinner(null);\n    setGenerals({});\n    setFilled(q.key);\n    setTried(false);\n  }\n\n  function add(list: \"mates\" | \"opps\" | \"ffa\", name: string) {\n    if (!byName[name]) return fb.error(tx.errUnknown(name));\n    if (everyone.includes(name)) return fb.error(tx.errDup);\n    if (list === \"mates\") setMates((x) => [...x, name]);\n    if (list === \"opps\") setOpps((x) => [...x, name]);\n    if (list === \"ffa\") setFfa((x) => [...x, name]);\n  }\n\n  function move(name: string) {\n    if (mates.includes(name) && opps.length < size) {\n      setMates((x) => x.filter((y) => y !== name));\n      setOpps((x) => [...x, name]);\n    } else if (opps.includes(name) && myTeam.length < size) {\n      setOpps((x) => x.filter((y) => y !== name));\n      setMates((x) => [...x, name]);\n    }\n  }\n\n  const problem = (() => {\n    if (team) {\n      if (myTeam.length > size || opps.length > size) return tx.hint.tooMany(size);\n      if (opps.length < 1) return tx.hint.players;\n      if (won === null) return tx.hint.result;\n    } else {\n      if (ffaPlayers.length < 2) return tx.hint.ffa;\n      if (!ffaWinner) return tx.hint.winner;\n    }\n    return null;\n  })();\n\n  async function submit() {\n    if (!me) return;\n    setTried(true);\n    if (problem) return;\n    const participants = team ? [...myTeam, ...opps] : ffaPlayers;\n    const winners = team ? (won ? myTeam : opps) : [ffaWinner!];\n    const g: Record<string, string> = {};\n    for (const p of participants) if (generals[p]) g[p] = generals[p] as string;\n    setSending(true);\n    const { error } = await supabase.from(\"match_submissions\").insert({\n      submitter_username: me.username, mode, participants, winners,\n      map: map.trim() || null, notes: notes.trim() || null, replay_url: replay.trim() || null, generals: g, match_date: date,\n    });\n    setSending(false);\n    if (error) return fb.error(error.message);\n    fb.success(tx.sent);\n    setMates([]); setOpps([]); setFfa([]); setWon(null); setFfaWinner(null); setGenerals({}); setMap(\"\"); setReplay(\"\"); setNotes(\"\"); setFilled(null); setTried(false);\n    await load(me.username, me.id);\n  }\n\n  async function answer(s: Sub, ok: boolean) {\n    if (!me) return;\n    let reason = \"\";\n    if (!ok) {\n      const r = await fb.prompt({ title: tx.disputeTitle, message: tx.disputeMsg, placeholder: tx.disputePh, multiline: true, confirmLabel: tx.dispute });\n      if (r === null) return;\n      reason = r;\n    }\n    setBusy(s.id);\n    const { error } = ok ? await supabase.rpc(\"confirm_submission\", { p_id: s.id }) : await supabase.rpc(\"dispute_submission\", { p_id: s.id, p_reason: reason });\n    setBusy(null);\n    if (error) return fb.error(error.message);\n    await load(me.username, me.id);\n  }\n\n  const fmt = (d: string) => new Date(d + (d.length === 10 ? \"T12:00:00\" : \"\")).toLocaleDateString(lang === \"ar\" ? \"ar-EG\" : \"en-US\", { month: \"short\", day: \"numeric\", year: \"numeric\" });\n  const canAnswer = (s: Sub) => !!me && s.status === \"pending\" && s.submitter_username !== me.username && (s.mode === \"ffa\" || s.winners.includes(me.username) !== s.winners.includes(s.submitter_username));\n  const needs = subs.filter(canAnswer);\n  const mine = subs.filter((s) => !canAnswer(s));\n  const avatar = (n: string, s = 32, ring: string = C.lineStrong) => (\n    // eslint-disable-next-line @next/next/no-img-element\n    <img src={byName[n]?.avatar || \"/default-avatar.svg\"} alt=\"\" className=\"shrink-0 rounded-full object-cover\" style={{ width: s, height: s, border: `2px solid ${ring}` }} />\n  );\n\n  const playerRow = (p: string, side: \"mates\" | \"opps\" | \"ffa\") => {\n    const isMe = p === me?.username;\n    const color = side === \"opps\" ? LOSS : C.amber;\n    return (\n      <li key={p} className=\"czr-row czr-pop flex items-center gap-2 border px-2 py-1.5\" style={{ borderColor: C.line, background: \"#0A0C08\" }}>\n        {side === \"ffa\" && (\n          <button type=\"button\" onClick={() => setFfaWinner(p)} aria-pressed={ffaWinner === p} aria-label={`${p} — ${tx.winner}`} className=\"inline-flex h-9 w-9 shrink-0 items-center justify-center border\" style={{ background: ffaWinner === p ? C.amber : \"transparent\", borderColor: ffaWinner === p ? C.amber : C.lineStrong, color: ffaWinner === p ? C.void : C.muted }}>\n            <Crown size={15} aria-hidden=\"true\" />\n          </button>\n        )}\n        {avatar(p, 30, isMe ? C.amber : color)}\n        <span className=\"min-w-0 flex-1\">\n          <span className=\"block truncate text-sm\" style={{ fontWeight: isMe ? 800 : 600, color: isMe ? C.amber : C.paper }}>{p}</span>\n          <span className=\"block text-[10px] uppercase tracking-wider\" style={{ color: C.muted, ...mono }}>{tierOf(byName[p]?.rating ?? 1000)[lang]}</span>\n        </span>\n        <GeneralSelect compact lang={lang} value={generals[p] ?? \"\"} onChange={(v) => setGenerals((g) => ({ ...g, [p]: v }))} label={p} />\n        {side !== \"ffa\" && !isMe && (\n          <button type=\"button\" onClick={() => move(p)} aria-label={`${tx.move}: ${p}`} title={tx.move} className=\"inline-flex h-9 w-9 shrink-0 items-center justify-center border\" style={{ borderColor: C.lineStrong, color: C.muted }}><ArrowLeftRight size={14} aria-hidden=\"true\" /></button>\n        )}\n        {!isMe ? (\n          <button type=\"button\" onClick={() => (side === \"mates\" ? setMates((x) => x.filter((y) => y !== p)) : side === \"opps\" ? setOpps((x) => x.filter((y) => y !== p)) : (setFfa((x) => x.filter((y) => y !== p)), ffaWinner === p && setFfaWinner(null)))} aria-label={`${tx.remove}: ${p}`} className=\"inline-flex h-9 w-9 shrink-0 items-center justify-center\" style={{ color: C.muted }}><X size={15} aria-hidden=\"true\" /></button>\n        ) : <span className=\"w-9 shrink-0\" />}\n      </li>\n    );\n  };\n\n  const teamCol = (side: \"mates\" | \"opps\", list: string[], label: string, color: string) => (\n    <div className=\"flex flex-col border\" style={{ borderColor: (side === \"mates\" && won === true) || (side === \"opps\" && won === false) ? C.radar : C.line, background: \"#0E110B\", transition: \"border-color 0.3s ease\" }}>\n      <div className=\"flex items-center justify-between border-b px-4 py-2.5\" style={{ borderColor: C.line }}>\n        <span className=\"cz-display flex items-center gap-2 text-lg uppercase\" style={{ color, fontWeight: 700 }}>\n          {label}\n          {((side === \"mates\" && won === true) || (side === \"opps\" && won === false)) && <Crown size={15} style={{ color: C.radar }} aria-hidden=\"true\" />}\n        </span>\n        <span className=\"text-xs tabular-nums\" style={{ color: list.length === size ? C.radar : C.muted, ...mono }}>{list.length}/{size}</span>\n      </div>\n      <ul className=\"flex flex-col gap-2 p-3\">{list.map((p) => playerRow(p, side))}</ul>\n      {list.length < size && (\n        <div className=\"px-3 pb-3\"><PlayerPicker people={people} exclude={everyone} onPick={(n) => add(side, n)} placeholder={tx.search} noMatch={tx.noMatch} lang={lang} /></div>\n      )}\n    </div>\n  );\n\n  const steps = (s: Sub) => {\n    const level = s.status === \"pending\" ? 1 : s.status === \"confirmed\" || s.status === \"disputed\" ? 2 : 3;\n    const bad = s.status === \"rejected\" || s.status === \"disputed\";\n    return (\n      <div className=\"flex items-center gap-1.5\" dir=\"ltr\" aria-hidden=\"true\">\n        {[1, 2, 3].map((i) => (\n          <span key={i} className=\"h-1.5 w-8\" style={{ background: i <= level ? (bad && i === level ? LOSS : i === 3 ? C.radar : C.amber) : C.line }} />\n        ))}\n      </div>\n    );\n  };\n\n  const STATUS: Record<Sub[\"status\"], { color: string; icon: typeof Clock }> = {\n    pending: { color: C.amber, icon: Clock }, confirmed: { color: C.radar, icon: ShieldCheck }, disputed: { color: LOSS, icon: Flag }, approved: { color: C.radar, icon: Check }, rejected: { color: LOSS, icon: Ban },\n  };\n\n  const reportCard = (s: Sub, actions: boolean) => {\n    const st = STATUS[s.status];\n    const losers = s.participants.filter((p) => !s.winners.includes(p));\n    const g = readGenerals(s.generals);\n    const name = (p: string) => (g[p] ? `${p} (${generalShort(g[p], lang)})` : p);\n    return (\n      <li key={s.id} className=\"czr-in relative border\" style={{ borderColor: actions ? \"rgba(220,38,38,0.6)\" : C.line, background: actions ? \"linear-gradient(120deg, rgba(220,38,38,0.10), #0A0C08 60%)\" : \"#0A0C08\" }}>\n        <div className=\"flex flex-wrap items-center gap-x-4 gap-y-2 border-b px-4 py-2.5 text-xs\" style={{ borderColor: C.line, color: C.muted }}>\n          <span className=\"uppercase tracking-widest\" style={{ color: C.amber, fontWeight: 700, ...mono }}>{s.mode}</span>\n          <span>{fmt(s.match_date)}</span>\n          {s.map && <span className=\"inline-flex items-center gap-1\"><MapIcon size={11} aria-hidden=\"true\" />{s.map}</span>}\n          <span>{tx.reportedBy} <b style={{ color: C.paper }}>{s.submitter_username}</b></span>\n          <span className=\"ms-auto flex items-center gap-3\">{steps(s)}<span className=\"inline-flex items-center gap-1.5\" style={{ color: st.color, fontWeight: 700 }}><st.icon size={13} aria-hidden=\"true\" />{tx.st[s.status]}</span></span>\n        </div>\n        <div className=\"flex flex-wrap items-center gap-3 px-4 py-3 text-sm\">\n          <span style={{ color: C.radar, fontWeight: 700 }}>▲ {s.winners.map(name).join(\" + \")}</span>\n          <span className=\"text-xs uppercase\" style={{ color: C.lineStrong, ...mono }}>{tx.vs}</span>\n          <span style={{ color: LOSS }}>▼ {losers.map(name).join(\" + \")}</span>\n          {s.replay_url && <a href={s.replay_url} target=\"_blank\" rel=\"noopener noreferrer\" className=\"inline-flex items-center gap-1 text-xs hover:underline\" style={{ color: C.amber }}><Link2 size={12} aria-hidden=\"true\" />replay</a>}\n        </div>\n        {s.dispute_reason && <p className=\"px-4 pb-3 text-xs\" style={{ color: LOSS }}>“{s.dispute_reason}”</p>}\n        {actions && (\n          <div className=\"flex flex-wrap justify-end gap-2 border-t px-4 py-3\" style={{ borderColor: C.line }}>\n            <button type=\"button\" onClick={() => answer(s, false)} disabled={busy === s.id} className=\"inline-flex min-h-[42px] items-center gap-2 border px-4 text-xs uppercase tracking-widest disabled:opacity-50\" style={{ borderColor: \"rgba(248,113,113,0.6)\", color: LOSS }}><Flag size={14} aria-hidden=\"true\" />{tx.dispute}</button>\n            <button type=\"button\" onClick={() => answer(s, true)} disabled={busy === s.id} className=\"inline-flex min-h-[42px] items-center gap-2 px-5 text-xs uppercase tracking-widest disabled:opacity-50\" style={{ background: C.radar, color: C.void, fontWeight: 800 }}>\n              {busy === s.id ? <Loader2 size={14} className=\"animate-spin\" aria-hidden=\"true\" /> : <Check size={14} aria-hidden=\"true\" />}{tx.confirm}\n            </button>\n          </div>\n        )}\n      </li>\n    );\n  };\n\n  // live preview sentence\n  const preview = (() => {\n    const mapPart = map.trim() ? ` ${tx.on} ${map.trim()}` : \"\";\n    if (team) {\n      if (!opps.length) return null;\n      const w = won === null ? null : won ? myTeam : opps;\n      const l = won === null ? null : won ? opps : myTeam;\n      if (!w || !l) return { text: `${myTeam.join(\" + \")} ${tx.vs} ${opps.join(\" + \")}`, sub: `${mode.toUpperCase()}${mapPart} · ${fmt(date)}`, ok: false };\n      return { text: `${w.join(\" + \")} ${tx.defeated} ${l.join(\" + \")}`, sub: `${mode.toUpperCase()}${mapPart} · ${fmt(date)}`, ok: true };\n    }\n    if (ffaPlayers.length < 2) return null;\n    if (!ffaWinner) return { text: ffaPlayers.join(\" · \"), sub: `FFA${mapPart} · ${fmt(date)}`, ok: false };\n    return { text: `${ffaWinner} ${tx.won} ${ffaPlayers.filter((p) => p !== ffaWinner).join(\", \")}`, sub: `FFA${mapPart} · ${fmt(date)}`, ok: true };\n  })();\n\n  return (\n    <main className=\"relative min-h-screen w-full overflow-x-clip pb-24\" style={{ background: C.void, color: C.paper }}>\n      <style>{CSS}</style>\n      <div aria-hidden=\"true\" className=\"pointer-events-none absolute inset-x-0 top-0 h-[520px]\" style={{ background: \"radial-gradient(ellipse 55% 60% at 80% 10%, rgba(232,166,61,0.10), transparent 65%)\" }} />\n\n      <header className=\"relative border-b\" style={{ borderColor: C.line }}>\n        <div className={`${WRAP} pb-10 pt-12 md:pt-16`}>\n          <div className=\"czr-in flex items-center gap-2 text-[11px] uppercase tracking-[0.3em]\" style={{ color: C.radar, ...mono }}><ClipboardCheck size={14} aria-hidden=\"true\" />{tx.eyebrow}</div>\n          <h1 className=\"czr-in cz-display mt-3 uppercase leading-[0.88]\" style={{ fontSize: \"clamp(2.8rem, 7vw, 5.5rem)\", fontWeight: 700, animationDelay: \"0.05s\" }}>{tx.title}</h1>\n          <p className=\"czr-in mt-4 max-w-2xl text-base leading-relaxed\" style={{ color: C.muted, animationDelay: \"0.1s\" }}>{tx.sub}</p>\n          <ol className=\"czr-in mt-7 flex flex-wrap items-center gap-2\" style={{ animationDelay: \"0.15s\" }}>\n            {tx.steps.map((s, i) => (\n              <li key={s} className=\"flex items-center gap-2\">\n                <span className=\"inline-flex items-center gap-2 border px-3 py-2 text-xs uppercase tracking-[0.14em]\" style={{ borderColor: i === 0 ? C.amber : C.lineStrong, color: i === 0 ? C.amber : C.muted, background: i === 0 ? \"rgba(232,166,61,0.08)\" : \"transparent\", ...mono }}>\n                  <span className=\"inline-flex h-5 w-5 items-center justify-center text-[11px]\" style={{ background: i === 0 ? C.amber : C.line, color: i === 0 ? C.void : C.paper, fontWeight: 800 }}>{i + 1}</span>\n                  {s}\n                </span>\n                {i < 2 && <ChevronRight size={14} className=\"rtl:-scale-x-100\" style={{ color: C.lineStrong }} aria-hidden=\"true\" />}\n              </li>\n            ))}\n          </ol>\n        </div>\n      </header>\n\n      <div className={`${WRAP} relative mt-8 flex flex-col gap-6`}>\n        {me === undefined ? (\n          <Loader2 size={22} className=\"animate-spin\" style={{ color: C.muted }} aria-hidden=\"true\" />\n        ) : me === null ? (\n          <div className=\"flex flex-wrap items-center gap-4 border p-6\" style={{ borderColor: C.amberDim, background: \"#0E110B\" }}>\n            <span className=\"flex-1\">{tx.signIn}</span>\n            <Link href=\"/login\" className=\"inline-flex min-h-[44px] items-center gap-2 px-5 text-xs uppercase tracking-widest\" style={{ background: C.amber, color: C.void, fontWeight: 700 }}><LogIn size={15} className=\"rtl:-scale-x-100\" aria-hidden=\"true\" />{tx.login}</Link>\n          </div>\n        ) : !ready ? (\n          <p className=\"flex items-start gap-2 border p-5 text-sm\" style={{ borderColor: C.amberDim, background: \"#0E110B\", color: C.muted }}><Info size={17} className=\"mt-0.5 shrink-0\" style={{ color: C.amber }} aria-hidden=\"true\" />{tx.notReady}</p>\n        ) : (\n          <>\n            {needs.length > 0 && (\n              <Section code=\"!!\" title={`${tx.needs} · ${needs.length}`} icon={Flag} accent={RED}>\n                <p className=\"-mt-1 mb-4 text-sm\" style={{ color: C.muted }}>{tx.needsSub}</p>\n                <ul className=\"flex flex-col gap-3\">{needs.map((s) => reportCard(s, true))}</ul>\n              </Section>\n            )}\n\n            {me.banned ? (\n              <p className=\"border p-5 text-sm\" style={{ borderColor: \"rgba(248,113,113,0.5)\", color: LOSS }}>{tx.banned}</p>\n            ) : (\n              <>\n                {quick.length > 0 && (\n                  <Section code=\"01\" title={tx.quick} icon={Zap}>\n                    <p className=\"-mt-1 mb-4 text-xs\" style={{ color: C.muted }}>{tx.quickSub}</p>\n                    <div className=\"grid gap-3 sm:grid-cols-2 lg:grid-cols-3\">\n                      {quick.map((q) => (\n                        <button key={q.key} type=\"button\" onClick={() => applyQuick(q)} aria-pressed={filled === q.key} className=\"czr-card flex items-center gap-3 border p-3 text-start\" style={{ borderColor: filled === q.key ? C.amber : C.line, background: filled === q.key ? \"rgba(232,166,61,0.08)\" : \"#0A0C08\", boxShadow: filled === q.key ? \"0 0 20px rgba(232,166,61,0.15)\" : \"none\" }}>\n                          <span className=\"inline-flex h-10 w-10 shrink-0 items-center justify-center\" style={{ border: `1px solid ${q.kind === \"challenge\" ? RED : C.amberDim}`, color: q.kind === \"challenge\" ? RED : C.amber }}>\n                            {q.kind === \"challenge\" ? <Swords size={17} aria-hidden=\"true\" /> : <RotateCcw size={17} aria-hidden=\"true\" />}\n                          </span>\n                          <span className=\"min-w-0 flex-1\">\n                            <span className=\"block text-[10px] uppercase tracking-[0.18em]\" style={{ color: q.kind === \"challenge\" ? LOSS : C.muted, ...mono }}>{q.kind === \"challenge\" ? tx.fromChallenge : tx.rematch} · {q.sub}</span>\n                            <span className=\"block truncate text-sm\" style={{ fontWeight: 700 }}>{q.label}</span>\n                          </span>\n                          {filled === q.key ? <Check size={16} style={{ color: C.amber }} aria-hidden=\"true\" /> : <span className=\"text-[11px] uppercase tracking-widest\" style={{ color: C.amber }}>{tx.use}</span>}\n                        </button>\n                      ))}\n                    </div>\n                  </Section>\n                )}\n\n                <Section code={quick.length ? \"02\" : \"01\"} title={tx.title} icon={FileText}>\n                  {/* mode */}\n                  <div className=\"flex flex-wrap items-center gap-3\">\n                    <span className=\"text-[10px] uppercase tracking-[0.25em]\" style={{ color: C.muted, ...mono }}>{tx.mode}</span>\n                    <div className=\"grid grid-cols-4 gap-2\" role=\"group\" dir=\"ltr\">\n                      {MODES.map((m) => (\n                        <button key={m} type=\"button\" aria-pressed={mode === m} onClick={() => { setMode(m); setWon(null); setFfaWinner(null); setFilled(null); }} className=\"min-h-[46px] min-w-[64px] border px-3\" style={{ background: mode === m ? \"linear-gradient(180deg, rgba(232,166,61,0.25), rgba(232,166,61,0.08))\" : \"#0A0C08\", borderColor: mode === m ? C.amber : C.lineStrong }}>\n                          <span className=\"cz-display text-lg uppercase\" style={{ color: mode === m ? C.amber : C.paper, fontWeight: 700 }}>{m}</span>\n                        </button>\n                      ))}\n                    </div>\n                    {filled?.startsWith(\"c:\") && mode === \"ffa\" && quick.find((q) => q.key === filled)?.sub === \"1V1\" && <span className=\"text-xs\" style={{ color: C.muted }}>{tx.oneVone}</span>}\n                  </div>\n\n                  {/* sides */}\n                  {team ? (\n                    <div className=\"mt-5 grid gap-4 md:grid-cols-[1fr_auto_1fr] md:items-start\">\n                      {teamCol(\"mates\", myTeam, tx.yourTeam, C.amber)}\n                      <div className=\"flex items-center justify-center py-1 md:py-10\"><span className=\"cz-display text-2xl\" style={{ color: C.lineStrong, fontWeight: 700 }}>{tx.vs.toUpperCase()}</span></div>\n                      {teamCol(\"opps\", opps, tx.opponents, LOSS)}\n                    </div>\n                  ) : (\n                    <div className=\"mt-5 border\" style={{ borderColor: C.line, background: \"#0E110B\" }}>\n                      <div className=\"flex items-center justify-between border-b px-4 py-2.5\" style={{ borderColor: C.line }}>\n                        <span className=\"cz-display text-lg uppercase\" style={{ color: C.amber, fontWeight: 700 }}>{tx.players}</span>\n                        <span className=\"text-xs\" style={{ color: C.muted }}>{tx.pickWinner}</span>\n                      </div>\n                      <ul className=\"flex flex-col gap-2 p-3\">{ffaPlayers.map((p) => playerRow(p, \"ffa\"))}</ul>\n                      {ffaPlayers.length < SIZE.ffa && <div className=\"px-3 pb-3\"><PlayerPicker people={people} exclude={everyone} onPick={(n) => add(\"ffa\", n)} placeholder={tx.search} noMatch={tx.noMatch} lang={lang} /></div>}\n                    </div>\n                  )}\n\n                  {/* result */}\n                  {team && (\n                    <div className=\"mt-5 grid grid-cols-2 gap-3\">\n                      {[true, false].map((v) => {\n                        const on = won === v;\n                        const col = v ? C.radar : LOSS;\n                        return (\n                          <button key={String(v)} type=\"button\" aria-pressed={on} onClick={() => setWon(v)} className=\"czr-card flex items-center gap-4 border p-4 text-start\" style={{ borderColor: on ? col : C.lineStrong, background: on ? `linear-gradient(120deg, ${v ? \"rgba(143,191,79,0.18)\" : \"rgba(220,38,38,0.16)\"}, #0A0C08 70%)` : \"#0A0C08\", boxShadow: on ? `0 0 24px ${v ? \"rgba(143,191,79,0.2)\" : \"rgba(220,38,38,0.2)\"}` : \"none\" }}>\n                            <span className=\"inline-flex h-12 w-12 shrink-0 items-center justify-center\" style={{ background: on ? col : \"transparent\", border: `1px solid ${col}`, color: on ? C.void : col }}>\n                              {v ? <Crown size={22} aria-hidden=\"true\" /> : <Skull size={22} aria-hidden=\"true\" />}\n                            </span>\n                            <span>\n                              <span className=\"cz-display block text-2xl uppercase leading-none\" style={{ color: on ? col : C.paper, fontWeight: 700 }}>{v ? tx.victory : tx.defeat}</span>\n                              <span className=\"mt-1 block text-xs\" style={{ color: C.muted }}>{v ? tx.victorySub : tx.defeatSub}</span>\n                            </span>\n                          </button>\n                        );\n                      })}\n                    </div>\n                  )}\n\n                  {/* details */}\n                  <div className=\"mt-6 text-[10px] uppercase tracking-[0.25em]\" style={{ color: C.muted, ...mono }}>{tx.details}</div>\n                  <div className=\"mt-2 grid gap-3 sm:grid-cols-2\">\n                    <label className=\"block\"><span className=\"mb-1.5 flex items-center gap-1.5 text-[11px] uppercase tracking-[0.16em]\" style={{ color: C.muted }}><MapIcon size={12} aria-hidden=\"true\" />{tx.mapLabel}</span>\n                      <input list=\"report-maps\" value={map} onChange={(e) => setMap(e.target.value)} className=\"min-h-[44px] w-full border border-[#3A4029] bg-[#0A0C08] px-3 text-sm text-[#EDEAE0] focus:border-[#E8A63D]\" />\n                      <datalist id=\"report-maps\">{MAP_FILES.map((m) => <option key={m.name} value={m.name} />)}</datalist>\n                    </label>\n                    <label className=\"block\"><span className=\"mb-1.5 flex items-center gap-1.5 text-[11px] uppercase tracking-[0.16em]\" style={{ color: C.muted }}><Calendar size={12} aria-hidden=\"true\" />{tx.date}</span>\n                      <input type=\"date\" value={date} max={new Date().toISOString().slice(0, 10)} onChange={(e) => setDate(e.target.value)} className=\"min-h-[44px] w-full border border-[#3A4029] bg-[#0A0C08] px-3 text-sm text-[#EDEAE0] focus:border-[#E8A63D]\" />\n                    </label>\n                    <label className=\"block\"><span className=\"mb-1.5 flex items-center gap-1.5 text-[11px] uppercase tracking-[0.16em]\" style={{ color: C.muted }}><Link2 size={12} aria-hidden=\"true\" />{tx.replay}</span>\n                      <input value={replay} onChange={(e) => setReplay(e.target.value)} placeholder={tx.replayPh} className=\"min-h-[44px] w-full border border-[#3A4029] bg-[#0A0C08] px-3 text-sm text-[#EDEAE0] focus:border-[#E8A63D]\" />\n                    </label>\n                    <label className=\"block\"><span className=\"mb-1.5 block text-[11px] uppercase tracking-[0.16em]\" style={{ color: C.muted }}>{tx.notes}</span>\n                      <input value={notes} maxLength={500} onChange={(e) => setNotes(e.target.value)} className=\"min-h-[44px] w-full border border-[#3A4029] bg-[#0A0C08] px-3 text-sm text-[#EDEAE0] focus:border-[#E8A63D]\" />\n                    </label>\n                  </div>\n\n                  {/* battle report preview */}\n                  <div className=\"relative mt-6 border p-4\" style={{ borderColor: preview?.ok ? C.radar : C.line, background: \"#0A0C08\", transition: \"border-color 0.3s ease\" }}>\n                    <div className=\"text-[10px] uppercase tracking-[0.25em]\" style={{ color: preview?.ok ? C.radar : C.muted, ...mono }}>▮ {tx.preview}</div>\n                    {preview ? (\n                      <>\n                        <div className=\"cz-display mt-1 text-xl uppercase leading-tight md:text-2xl\" style={{ fontWeight: 700, color: preview.ok ? C.paper : C.muted }}>{preview.text}</div>\n                        <div className=\"mt-1 text-xs\" style={{ color: C.muted, ...mono }}>{preview.sub}</div>\n                      </>\n                    ) : (\n                      <div className=\"mt-1 text-sm\" style={{ color: C.muted }}>{team ? tx.hint.players : tx.hint.ffa}</div>\n                    )}\n                    {problem && (preview || tried) && <div className=\"mt-2 text-xs\" role={tried ? \"alert\" : undefined} style={{ color: tried ? LOSS : C.amber }}>→ {problem}</div>}\n                  </div>\n\n                  <button type=\"button\" onClick={submit} disabled={sending} className=\"mt-5 inline-flex min-h-[56px] w-full items-center justify-center gap-2 text-sm uppercase tracking-[0.18em] transition-[filter,opacity] hover:brightness-110 disabled:opacity-60\" style={{ background: problem ? \"#3A4029\" : C.amber, color: problem ? C.paper : C.void, fontWeight: 800, boxShadow: problem ? \"none\" : \"0 0 30px rgba(232,166,61,0.3)\" }}>\n                    {sending ? <Loader2 size={18} className=\"animate-spin\" aria-hidden=\"true\" /> : <ClipboardCheck size={18} aria-hidden=\"true\" />}{sending ? tx.sending : tx.submit}\n                  </button>\n                </Section>\n              </>\n            )}\n\n            <Section code=\"RX\" title={tx.yours} icon={ClipboardCheck}>\n              {mine.length === 0 ? <p className=\"text-sm\" style={{ color: C.muted }}>{tx.none}</p> : <ul className=\"flex flex-col gap-3\">{mine.map((s) => reportCard(s, false))}</ul>}\n            </Section>\n          </>\n        )}\n      </div>\n    </main>\n  );\n}\n", "sig": "export default function ReportView", "drop": [], "skipIf": []}, {"path": "components/play/PlayView.tsx", "src": "\"use client\";\n\nimport { useCallback, useEffect, useMemo, useState, type ReactNode } from \"react\";\nimport Link from \"next/link\";\nimport { Crosshair, Radio, UserCheck, Check, X, Clock, BellRing, BellOff, Search, LogIn, Info, Loader2, Shield, Signal, Star, ArrowUpRight, Send, Satellite } from \"lucide-react\";\nimport { createClient } from \"@/lib/supabase/client\";\nimport { C } from \"@/lib/theme\";\nimport { useLanguage } from \"@/lib/i18n/LanguageContext\";\nimport { useFeedback } from \"@/components/FeedbackProvider\";\nimport { useOnlinePlayers } from \"@/lib/presence\";\nimport { PLAY_MODES, notifyServer, pushSupported, currentPushSubscription, enablePush, disablePush, type Challenge, type ReadyPlayer, type PlayMode } from \"@/lib/play\";\nimport ChallengeButton from \"@/components/play/ChallengeButton\";\n\nconst WRAP = \"mx-auto max-w-[1400px] px-5 md:px-12\";\nconst RED = \"#DC2626\";\nconst LOSS = \"#F87171\";\nconst SWEEP_S = 4; // seconds per radar turn\nconst DURATIONS = [30, 60, 120, 180];\n\nconst TIERS: [number, { en: string; ar: string }][] = [\n  [-Infinity, { en: \"Private\", ar: \"جندي\" }], [900, { en: \"Corporal\", ar: \"عريف\" }], [1000, { en: \"Sergeant\", ar: \"رقيب\" }], [1100, { en: \"Lieutenant\", ar: \"ملازم\" }],\n  [1200, { en: \"Captain\", ar: \"نقيب\" }], [1300, { en: \"Major\", ar: \"رائد\" }], [1400, { en: \"Colonel\", ar: \"عقيد\" }], [1500, { en: \"Brigadier General\", ar: \"عميد\" }],\n  [1600, { en: \"General\", ar: \"لواء\" }], [1700, { en: \"Commander\", ar: \"قائد\" }],\n];\nconst tierOf = (r: number) => TIERS.reduce((acc, [min, t]) => (r >= min ? t : acc), TIERS[0][1]);\n\n// Arabic needs a native review.\nconst TEXT = {\n  en: {\n    ticker: \"Command channel // Matchmaking\", nominal: \"All systems nominal\", utc: \"UTC\",\n    title: \"Find a game\", sub: \"Scan the field, deploy when you're ready, and challenge any commander on the network.\",\n    readiness: \"Combat readiness\", levels: [\"Quiet\", \"Low\", \"Elevated\", \"High\", \"Maximum\"],\n    online: \"Online\", ready: \"Ready\", incoming: \"Incoming\", status: \"Your status\", deployed: \"Deployed\", standby: \"Standby\",\n    radar: \"Tactical radar\", radarSub: \"Click a contact to lock on.\", you: \"You\", legendReady: \"Ready\", legendOnline: \"Online\",\n    noContacts: \"No other contacts on the network right now.\",\n    target: \"Target lock\", noTarget: \"Select a contact on the radar, or search below.\", rating: \"Team rating\", readyFor: \"Ready for\", onPage: \"On\",\n    left: (m: number) => `${m} min left`, profile: \"Profile\", acquired: \"Target acquired\",\n    deploy: \"Deploy\", deploySub: \"Tell every commander you're ready to fight.\", modes: \"Modes\", notePh: \"e.g. need 2 more for 4v4\", for: \"For\",\n    min: (m: number) => (m < 60 ? `${m} min` : `${m / 60} h`), goReady: \"I'm ready\", stop: \"Stand down\", postDiscord: \"Post in Discord\",\n    deployedFor: (m: number) => `Deployed — ${m} min left on the ready list`,\n    transmissions: \"Incoming transmissions\", noTransmissions: \"No orders waiting. The field is quiet.\", accept: \"Accept\", decline: \"Decline\", report: \"Report the result\", accepted: \"Accepted\",\n    units: \"Ready units\", noUnits: \"Nobody deployed yet. Be the first.\",\n    dispatched: \"Dispatched orders\", cancel: \"Cancel\", st: { pending: \"Awaiting reply\", accepted: \"Accepted — go play!\", declined: \"Declined\", cancelled: \"Cancelled\" }, expired: \"Expired\",\n    manual: \"Manual targeting\", manualPh: \"Type a commander's name\",\n    radio: \"Field radio\", radioOn: \"On — challenges ping this device\", radioOff: \"Get pinged on this phone or computer when someone challenges you.\", turnOn: \"Turn on\", turnOff: \"Turn off\",\n    radioNoSupport: \"Not available in this browser. On iPhone: install the app to your home screen first (Share → Add to Home Screen), then open it from there.\",\n    signIn: \"Sign in to deploy and challenge commanders.\", login: \"Log in\",\n    notReady: \"Find a game isn't switched on yet — an admin needs to run sql/play.sql once in Supabase.\",\n  },\n  ar: {\n    ticker: \"قناة القيادة // البحث عن مباراة\", nominal: \"كل الأنظمة تعمل\", utc: \"UTC\",\n    title: \"ابحث عن مباراة\", sub: \"امسح الميدان، انتشر عندما تكون جاهزاً، وتحدَّ أي قائد على الشبكة.\",\n    readiness: \"الجاهزية القتالية\", levels: [\"هادئ\", \"منخفض\", \"مرتفع\", \"عالٍ\", \"قصوى\"],\n    online: \"متصل\", ready: \"جاهز\", incoming: \"وارد\", status: \"حالتك\", deployed: \"منتشر\", standby: \"استعداد\",\n    radar: \"الرادار التكتيكي\", radarSub: \"اضغط على هدف لتثبيته.\", you: \"أنت\", legendReady: \"جاهز\", legendOnline: \"متصل\",\n    noContacts: \"لا توجد أهداف أخرى على الشبكة الآن.\",\n    target: \"تثبيت الهدف\", noTarget: \"اختر هدفاً على الرادار أو ابحث بالأسفل.\", rating: \"تقييم الفرق\", readyFor: \"جاهز لـ\", onPage: \"في\",\n    left: (m: number) => `باقي ${m} د`, profile: \"الملف\", acquired: \"تم تحديد الهدف\",\n    deploy: \"انتشار\", deploySub: \"أخبر كل القادة أنك جاهز للقتال.\", modes: \"الأنماط\", notePh: \"مثال: نحتاج لاعبَين لـ 4v4\", for: \"لمدة\",\n    min: (m: number) => (m < 60 ? `${m} د` : `${m / 60} س`), goReady: \"أنا جاهز\", stop: \"انسحاب\", postDiscord: \"انشر في ديسكورد\",\n    deployedFor: (m: number) => `منتشر — باقي ${m} دقيقة في قائمة الجاهزين`,\n    transmissions: \"إرسالات واردة\", noTransmissions: \"لا أوامر بانتظارك. الميدان هادئ.\", accept: \"قبول\", decline: \"رفض\", report: \"أبلغ عن النتيجة\", accepted: \"مقبول\",\n    units: \"وحدات جاهزة\", noUnits: \"لم ينتشر أحد بعد. كن الأول.\",\n    dispatched: \"أوامر مُرسلة\", cancel: \"إلغاء\", st: { pending: \"بانتظار الرد\", accepted: \"مقبول — العبوا!\", declined: \"مرفوض\", cancelled: \"ملغى\" }, expired: \"منتهي\",\n    manual: \"استهداف يدوي\", manualPh: \"اكتب اسم قائد\",\n    radio: \"اللاسلكي الميداني\", radioOn: \"مفعّل — ستصلك التحديات على هذا الجهاز\", radioOff: \"استلم تنبيهاً على هذا الهاتف أو الكمبيوتر عندما يتحداك أحد.\", turnOn: \"تفعيل\", turnOff: \"إيقاف\",\n    radioNoSupport: \"غير متاحة في هذا المتصفح. على الآيفون: ثبّت التطبيق على الشاشة الرئيسية أولاً ثم افتحه من هناك.\",\n    signIn: \"سجّل الدخول للانتشار وتحدي القادة.\", login: \"تسجيل الدخول\",\n    notReady: \"الميزة غير مفعّلة بعد — يجب على أحد المشرفين تشغيل sql/play.sql مرة واحدة في Supabase.\",\n  },\n};\n\nconst CSS = `\n@keyframes czw-sweep { to { transform: rotate(360deg); } }\n@keyframes czw-blip { 0% { opacity: 1; transform: translate(-50%, -50%) scale(1.35); filter: brightness(1.6); } 30% { opacity: 0.95; transform: translate(-50%, -50%) scale(1); filter: none; } 100% { opacity: 0.45; transform: translate(-50%, -50%) scale(1); } }\n@keyframes czw-ring { 0% { transform: scale(0.6); opacity: 0.8; } 100% { transform: scale(2.4); opacity: 0; } }\n@keyframes czw-in { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }\n@keyframes czw-scan { 0% { transform: translateY(-100%); } 100% { transform: translateY(100%); } }\n@keyframes czw-spin { to { transform: rotate(360deg); } }\n@keyframes czw-blink { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }\n@keyframes czw-ticker { from { transform: translateX(0); } to { transform: translateX(-50%); } }\n@keyframes czw-glitch { 0%, 94%, 100% { transform: none; text-shadow: none; } 95% { transform: translate(-2px, 1px); text-shadow: 2px 0 #8FBF4F, -2px 0 #DC2626; } 97% { transform: translate(2px, -1px); text-shadow: -2px 0 #8FBF4F, 2px 0 #DC2626; } }\n.czw-sweep { animation: czw-sweep ${SWEEP_S}s linear infinite; }\n.czw-blip { animation: czw-blip ${SWEEP_S}s linear infinite; }\n.czw-ring { animation: czw-ring 2s ease-out infinite; }\n.czw-in { animation: czw-in 0.55s cubic-bezier(0.2, 0.7, 0.2, 1) both; }\n.czw-scan { animation: czw-scan 2.6s linear infinite; }\n.czw-spin { animation: czw-spin 6s linear infinite; }\n.czw-blink { animation: czw-blink 1.1s steps(2) infinite; }\n.czw-ticker { animation: czw-ticker 30s linear infinite; }\n.czw-glitch { animation: czw-glitch 5s steps(1) infinite; }\n.czw-scanlines { background-image: repeating-linear-gradient(0deg, rgba(237,234,224,0.025) 0px, rgba(237,234,224,0.025) 1px, transparent 1px, transparent 3px); }\n.czw-plate { transition: transform 0.15s ease, background-color 0.2s ease, border-color 0.2s ease; }\n.czw-plate:active { transform: scale(0.97); }\n.czw-tag { transition: transform 0.25s ease, border-color 0.25s ease; }\n.czw-tag:hover { transform: translateY(-3px); border-color: #8A6425 !important; }\n@media (prefers-reduced-motion: reduce) {\n  .czw-sweep, .czw-blip, .czw-ring, .czw-in, .czw-scan, .czw-spin, .czw-blink, .czw-ticker, .czw-glitch { animation: none !important; }\n  .czw-blip { opacity: 1; transform: translate(-50%, -50%); }\n  .czw-tag:hover { transform: none; }\n}\n`;\n\nconst hash = (s: string) => {\n  let h = 2166136261;\n  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);\n  return (h >>> 0) / 4294967295;\n};\n\nfunction Brackets({ color = C.amberDim, size = 14 }: { color?: string; size?: number }) {\n  const s = { width: size, height: size, borderColor: color } as const;\n  return (\n    <span aria-hidden=\"true\" className=\"pointer-events-none absolute inset-0\">\n      <span className=\"absolute left-0 top-0 border-l-2 border-t-2\" style={s} />\n      <span className=\"absolute right-0 top-0 border-r-2 border-t-2\" style={s} />\n      <span className=\"absolute bottom-0 left-0 border-b-2 border-l-2\" style={s} />\n      <span className=\"absolute bottom-0 right-0 border-b-2 border-r-2\" style={s} />\n    </span>\n  );\n}\n\nfunction Panel({ code, icon: Icon, title, children, accent = C.amber, right, className = \"\", delay = 0 }: { code: string; icon: typeof Radio; title: string; children: ReactNode; accent?: string; right?: ReactNode; className?: string; delay?: number }) {\n  return (\n    <section className={`czw-in relative border ${className}`} style={{ background: \"linear-gradient(180deg, #12150E, #0E110B)\", borderColor: C.line, animationDelay: `${delay}s` }}>\n      <Brackets />\n      <header className=\"flex items-center justify-between gap-3 border-b px-5 py-3\" style={{ borderColor: C.line }}>\n        <h2 className=\"flex min-w-0 items-center gap-2.5\">\n          <span className=\"text-[10px] tracking-[0.2em]\" style={{ color: C.muted, fontFamily: \"var(--font-mono), monospace\" }}>{code}</span>\n          <Icon size={15} style={{ color: accent }} aria-hidden=\"true\" />\n          <span className=\"cz-display truncate text-lg uppercase\" style={{ fontWeight: 700, letterSpacing: \"0.04em\" }}>{title}</span>\n        </h2>\n        {right}\n      </header>\n      <div className=\"p-5\">{children}</div>\n    </section>\n  );\n}\n\ntype Contact = { username: string; ready?: ReadyPlayer; page?: string; rating: number; avatar: string | null };\n\nexport default function PlayView() {\n  const supabase = useMemo(() => createClient(), []);\n  const fb = useFeedback();\n  const { locale } = useLanguage();\n  const lang = locale === \"ar\" ? \"ar\" : \"en\";\n  const tx = TEXT[lang];\n  const online = useOnlinePlayers();\n\n  const [me, setMe] = useState<{ id: string; username: string } | null | undefined>(undefined);\n  const [ready, setReady] = useState<ReadyPlayer[]>([]);\n  const [challenges, setChallenges] = useState<Challenge[]>([]);\n  const [works, setWorks] = useState(true);\n  const [people, setPeople] = useState<Record<string, { avatar: string | null; rating: number }>>({});\n  const [modes, setModes] = useState<PlayMode[]>([\"2v2\"]);\n  const [note, setNote] = useState(\"\");\n  const [minutes, setMinutes] = useState(60);\n  const [postReady, setPostReady] = useState(true);\n  const [busy, setBusy] = useState<string | null>(null);\n  const [push, setPush] = useState<\"unsupported\" | \"off\" | \"on\" | \"loading\">(\"loading\");\n  const [find, setFind] = useState(\"\");\n  const [now, setNow] = useState(() => Date.now());\n  const [target, setTarget] = useState<string | null>(null);\n\n  const load = useCallback(async () => {\n    const [r, c] = await Promise.all([\n      supabase.from(\"ready_players\").select(\"*\").gt(\"until\", new Date().toISOString()).order(\"updated_at\", { ascending: false }),\n      supabase.from(\"challenges\").select(\"*\").order(\"created_at\", { ascending: false }).limit(40),\n    ]);\n    if (r.error) return setWorks(false);\n    setReady((r.data ?? []) as ReadyPlayer[]);\n    setChallenges((c.data ?? []) as Challenge[]);\n  }, [supabase]);\n\n  useEffect(() => {\n    (async () => {\n      const { data: { user } } = await supabase.auth.getUser();\n      if (user) {\n        const { data } = await supabase.from(\"profiles\").select(\"username\").eq(\"id\", user.id).single();\n        setMe(data?.username ? { id: user.id, username: data.username } : null);\n      } else setMe(null);\n      const { data: all } = await supabase.from(\"profiles\").select(\"username, avatar_url, rating_team\").eq(\"banned\", false).order(\"username\");\n      const list = (all ?? []) as { username: string; avatar_url: string | null; rating_team: number | null }[];\n      setPeople(Object.fromEntries(list.map((p) => [p.username, { avatar: p.avatar_url, rating: Math.round(Number(p.rating_team ?? 1000)) }])));\n      await load();\n    })();\n    const t = setInterval(() => void load(), 30_000);\n    const clock = setInterval(() => setNow(Date.now()), 1000);\n    return () => {\n      clearInterval(t);\n      clearInterval(clock);\n    };\n  }, [supabase, load]);\n\n  useEffect(() => {\n    if (!pushSupported()) return setPush(\"unsupported\");\n    currentPushSubscription().then((s) => setPush(s ? \"on\" : \"off\"));\n  }, []);\n\n  const mine = me ? ready.find((r) => r.user_id === me.id) : undefined;\n  const incoming = me ? challenges.filter((c) => c.to_user === me.id && c.status === \"pending\" && Date.parse(c.expires_at) > now) : [];\n  const recentAccepted = me ? challenges.filter((c) => c.to_user === me.id && c.status === \"accepted\").slice(0, 3) : [];\n  const outgoing = me ? challenges.filter((c) => c.from_user === me.id).slice(0, 8) : [];\n  const names = Object.keys(people);\n\n  // contacts on the radar: everyone online or ready, except you\n  const contacts = useMemo(() => {\n    const map = new Map<string, Contact>();\n    for (const o of online) if (o.username !== me?.username) map.set(o.username, { username: o.username, page: o.page, rating: people[o.username]?.rating ?? 1000, avatar: people[o.username]?.avatar ?? null });\n    for (const r of ready) if (r.username !== me?.username) map.set(r.username, { ...(map.get(r.username) ?? { username: r.username, rating: people[r.username]?.rating ?? 1000, avatar: people[r.username]?.avatar ?? null }), ready: r });\n    return Array.from(map.values());\n  }, [online, ready, people, me]);\n\n  // Radar positions: each player has a fixed spot (from their name); if two land too close,\n  // the later one is nudged around the ring until it has room for its label.\n  const blips = useMemo(() => {\n    const placed: { c: Contact; x: number; y: number; angle: number }[] = [];\n    for (const c of [...contacts].sort((a, b) => a.username.localeCompare(b.username))) {\n      let angle = hash(c.username) * 360;\n      const r = c.ready ? 18 + hash(c.username + \"r\") * 14 : 34 + hash(c.username + \"o\") * 10;\n      let x = 0, y = 0;\n      for (let i = 0; i < 36; i++) {\n        const rad = (angle * Math.PI) / 180;\n        x = 50 + Math.sin(rad) * r;\n        y = 50 - Math.cos(rad) * r;\n        if (placed.every((p) => Math.abs(p.x - x) > 16 || Math.abs(p.y - y) > 7)) break;\n        angle = (angle + 17) % 360;\n      }\n      placed.push({ c, x, y, angle });\n    }\n    return placed;\n  }, [contacts]);\n\n  useEffect(() => {\n    if (me === undefined) return; // still finding out who you are\n    if (target && target === me?.username) return setTarget(null);\n    if (!target && contacts.length) setTarget((contacts.find((c) => c.ready) ?? contacts[0]).username);\n  }, [contacts, target, me]);\n  const locked = contacts.find((c) => c.username === target) ?? (target && people[target] ? { username: target, rating: people[target].rating, avatar: people[target].avatar } : null);\n\n  const readiness = Math.min(4, Math.floor(ready.length / 2) + (online.length >= 5 ? 1 : 0) + (ready.length ? 1 : 0));\n  const readinessColor = [C.muted, C.radar, C.amber, \"#F59E0B\", RED][readiness];\n\n  async function goReady() {\n    if (!me || modes.length === 0) return;\n    setBusy(\"ready\");\n    const { error } = await supabase.from(\"ready_players\").upsert({ user_id: me.id, username: me.username, modes, note: note.trim() || null, until: new Date(Date.now() + minutes * 60_000).toISOString(), updated_at: new Date().toISOString() });\n    setBusy(null);\n    if (error) return fb.error(error.message);\n    void notifyServer(\"ready\", undefined, postReady);\n    load();\n  }\n  async function stopReady() {\n    if (!me) return;\n    setBusy(\"ready\");\n    await supabase.from(\"ready_players\").delete().eq(\"user_id\", me.id);\n    setBusy(null);\n    load();\n  }\n  async function respond(c: Challenge, accept: boolean) {\n    setBusy(c.id);\n    const { error } = await supabase.rpc(\"respond_challenge\", { p_id: c.id, p_accept: accept });\n    setBusy(null);\n    if (error) return fb.error(error.message);\n    void notifyServer(\"challenge\", c.id, accept);\n    load();\n  }\n  async function cancel(c: Challenge) {\n    setBusy(c.id);\n    const { error } = await supabase.rpc(\"cancel_challenge\", { p_id: c.id });\n    setBusy(null);\n    if (error) return fb.error(error.message);\n    load();\n  }\n  async function togglePush() {\n    setPush(\"loading\");\n    if (push === \"on\") {\n      await disablePush();\n      return setPush(\"off\");\n    }\n    const err = await enablePush();\n    if (err) {\n      fb.error(err);\n      return setPush(\"off\");\n    }\n    setPush(\"on\");\n  }\n\n  const minsLeft = (iso: string) => Math.max(1, Math.round((Date.parse(iso) - now) / 60000));\n  const ago = (iso: string) => {\n    const m = Math.max(0, Math.round((now - Date.parse(iso)) / 60000));\n    return new Intl.RelativeTimeFormat(lang, { numeric: \"auto\" }).format(m > 59 ? -Math.round(m / 60) : -m, m > 59 ? \"hour\" : \"minute\");\n  };\n  const avatar = (n: string, s: number, ring: string = C.lineStrong) => (\n    // eslint-disable-next-line @next/next/no-img-element\n    <img src={people[n]?.avatar || \"/default-avatar.svg\"} alt=\"\" className=\"shrink-0 rounded-full object-cover\" style={{ width: s, height: s, border: `2px solid ${ring}` }} />\n  );\n  const clock = new Date(now).toISOString().slice(11, 19);\n  const findMatch = names.find((n) => n.toLowerCase() === find.trim().toLowerCase() && n !== me?.username);\n  const mono = { fontFamily: \"var(--font-mono), monospace\" } as const;\n\n  return (\n    <main className=\"relative min-h-screen w-full overflow-x-clip pb-24\" style={{ background: C.void, color: C.paper }}>\n      <style>{CSS}</style>\n      <div aria-hidden=\"true\" className=\"czw-scanlines pointer-events-none fixed inset-0 z-0\" />\n      <div aria-hidden=\"true\" className=\"pointer-events-none absolute inset-x-0 top-0 h-[620px]\" style={{ background: \"radial-gradient(ellipse 60% 55% at 70% 20%, rgba(143,191,79,0.10), transparent 65%), radial-gradient(ellipse 50% 50% at 10% 0%, rgba(220,38,38,0.08), transparent 60%)\" }} />\n\n      {/* ticker */}\n      <div className=\"relative z-[1] overflow-hidden border-b\" style={{ borderColor: C.line, background: \"#070806\" }} dir=\"ltr\">\n        <div className=\"czw-ticker flex w-max gap-12 whitespace-nowrap py-2 text-[11px] uppercase tracking-[0.3em]\" style={{ color: C.muted, ...mono }}>\n          {[0, 1].map((k) => (\n            <span key={k} className=\"flex gap-12\">\n              <span><span style={{ color: C.radar }}>●</span> {tx.ticker}</span>\n              <span>{tx.online}: {online.length}</span>\n              <span>{tx.ready}: {ready.length}</span>\n              <span style={{ color: readinessColor }}>{tx.readiness}: {tx.levels[readiness]}</span>\n              <span>{tx.nominal}</span>\n              <span>{clock} {tx.utc}</span>\n            </span>\n          ))}\n        </div>\n      </div>\n\n      {/* hero */}\n      <header className=\"relative z-[1]\">\n        <div className={`${WRAP} pb-8 pt-12 md:pt-16`}>\n          <div className=\"flex flex-wrap items-end justify-between gap-6\">\n            <div className=\"czw-in\">\n              <div className=\"flex items-center gap-2 text-[11px] uppercase tracking-[0.3em]\" style={{ color: C.radar, ...mono }}>\n                <Satellite size={14} aria-hidden=\"true\" />\n                <span className=\"czw-blink inline-block h-1.5 w-1.5 rounded-full\" style={{ background: RED }} />\n                Live · {clock} {tx.utc}\n              </div>\n              <h1 className=\"czw-glitch cz-display mt-3 uppercase leading-[0.85]\" style={{ fontSize: \"clamp(3.2rem, 9vw, 7.5rem)\", fontWeight: 700, color: C.paper }}>{tx.title}</h1>\n              <p className=\"mt-4 max-w-xl text-base leading-relaxed\" style={{ color: C.muted }}>{tx.sub}</p>\n            </div>\n            {/* readiness gauge */}\n            <div className=\"czw-in relative w-full max-w-[360px] border p-4\" style={{ borderColor: C.line, background: \"#0E110B\", animationDelay: \"0.1s\" }}>\n              <Brackets color={readinessColor} size={10} />\n              <div className=\"flex items-center justify-between text-[10px] uppercase tracking-[0.25em]\" style={{ color: C.muted, ...mono }}>\n                <span>{tx.readiness}</span>\n                <span style={{ color: readinessColor, fontWeight: 700 }}>{tx.levels[readiness]}</span>\n              </div>\n              <div className=\"mt-3 grid grid-cols-5 gap-1.5\" dir=\"ltr\">\n                {[0, 1, 2, 3, 4].map((i) => (\n                  <span key={i} className=\"h-3\" style={{ background: i <= readiness ? [C.radar, C.radar, C.amber, \"#F59E0B\", RED][i] : C.line, boxShadow: i <= readiness && i === readiness ? `0 0 12px ${readinessColor}` : \"none\", transition: \"background 0.4s ease\" }} />\n                ))}\n              </div>\n            </div>\n          </div>\n\n          {/* HUD stats */}\n          <div className=\"czw-in mt-8 grid grid-cols-2 gap-px border md:grid-cols-4\" style={{ background: C.line, borderColor: C.line, animationDelay: \"0.15s\" }}>\n            {[\n              { label: tx.online, value: online.length, color: C.radar, icon: Signal },\n              { label: tx.ready, value: ready.length, color: C.amber, icon: UserCheck },\n              { label: tx.incoming, value: incoming.length, color: incoming.length ? RED : C.muted, icon: Radio },\n              { label: tx.status, value: mine ? tx.deployed : tx.standby, color: mine ? C.radar : C.muted, icon: Shield },\n            ].map((s) => (\n              <div key={s.label} className=\"relative min-w-0 px-4 py-4 sm:px-5\" style={{ background: \"#0E110B\" }}>\n                <div className=\"flex items-center gap-1.5 text-[10px] uppercase tracking-[0.25em]\" style={{ color: C.muted, ...mono }}><s.icon size={12} aria-hidden=\"true\" />{s.label}</div>\n                <div className=\"cz-display mt-1 truncate text-3xl uppercase leading-none tabular-nums sm:text-4xl\" style={{ color: s.color, fontWeight: 700 }}>{s.value}</div>\n              </div>\n            ))}\n          </div>\n        </div>\n      </header>\n\n      <div className={`${WRAP} relative z-[1]`}>\n        {me === null && (\n          <div className=\"czw-in mb-6 flex flex-wrap items-center gap-4 border p-5\" style={{ borderColor: C.amberDim, background: \"#0E110B\" }}>\n            <span className=\"flex-1\">{tx.signIn}</span>\n            <Link href=\"/login\" className=\"inline-flex min-h-[44px] items-center gap-2 px-5 text-xs uppercase tracking-widest\" style={{ background: C.amber, color: C.void, fontWeight: 700 }}><LogIn size={15} className=\"rtl:-scale-x-100\" aria-hidden=\"true\" />{tx.login}</Link>\n          </div>\n        )}\n        {!works && <p className=\"mb-6 flex items-start gap-2 border p-5 text-sm\" style={{ borderColor: C.amberDim, background: \"#0E110B\", color: C.muted }}><Info size={17} className=\"mt-0.5 shrink-0\" style={{ color: C.amber }} aria-hidden=\"true\" />{tx.notReady}</p>}\n\n        {/* ===== radar + target lock ===== */}\n        <div className=\"grid gap-6 lg:grid-cols-[minmax(0,1.25fr)_minmax(0,1fr)]\">\n          <Panel code=\"01\" icon={Crosshair} title={tx.radar} accent={C.radar} delay={0.2}\n            right={<span className=\"hidden items-center gap-4 text-[10px] uppercase tracking-[0.2em] sm:flex\" style={{ color: C.muted, ...mono }}><span className=\"inline-flex items-center gap-1.5\"><span className=\"h-2 w-2 rounded-full\" style={{ background: C.amber }} />{tx.legendReady}</span><span className=\"inline-flex items-center gap-1.5\"><span className=\"h-2 w-2 rounded-full\" style={{ background: C.radar }} />{tx.legendOnline}</span></span>}>\n            <p className=\"-mt-1 mb-4 text-xs\" style={{ color: C.muted }}>{tx.radarSub}</p>\n            <div className=\"relative mx-auto aspect-square w-full max-w-[560px]\" dir=\"ltr\">\n              {/* scope */}\n              <div className=\"absolute inset-0 overflow-hidden rounded-full\" style={{ background: \"radial-gradient(circle, rgba(143,191,79,0.10), rgba(10,12,8,0.95) 70%)\", border: `2px solid ${C.radar}`, boxShadow: \"0 0 40px rgba(143,191,79,0.15), inset 0 0 60px rgba(0,0,0,0.6)\" }}>\n                <svg viewBox=\"0 0 100 100\" className=\"absolute inset-0 h-full w-full\" aria-hidden=\"true\">\n                  {[16, 30, 44].map((r) => <circle key={r} cx=\"50\" cy=\"50\" r={r} fill=\"none\" stroke={C.lineStrong} strokeWidth=\"0.3\" />)}\n                  <line x1=\"50\" y1=\"2\" x2=\"50\" y2=\"98\" stroke={C.lineStrong} strokeWidth=\"0.25\" />\n                  <line x1=\"2\" y1=\"50\" x2=\"98\" y2=\"50\" stroke={C.lineStrong} strokeWidth=\"0.25\" />\n                  {Array.from({ length: 36 }, (_, i) => {\n                    const a = (i * 10 * Math.PI) / 180, long = i % 3 === 0;\n                    return <line key={i} x1={50 + Math.sin(a) * 48} y1={50 - Math.cos(a) * 48} x2={50 + Math.sin(a) * (long ? 45 : 46.5)} y2={50 - Math.cos(a) * (long ? 45 : 46.5)} stroke={C.radar} strokeWidth={long ? 0.5 : 0.25} opacity=\"0.6\" />;\n                  })}\n                  {[\"N\", \"E\", \"S\", \"W\"].map((d, i) => <text key={d} x={50 + [0, 41, 0, -41][i]} y={50 + [-39, 1.5, 42, 1.5][i]} textAnchor=\"middle\" fontSize=\"3\" fill={C.muted} style={mono}>{d}</text>)}\n                </svg>\n                <div className=\"czw-sweep absolute inset-0\" style={{ background: \"conic-gradient(from 0deg, rgba(143,191,79,0) 0deg, rgba(143,191,79,0) 300deg, rgba(143,191,79,0.08) 330deg, rgba(143,191,79,0.55) 360deg)\" }} />\n              </div>\n              {/* you */}\n              <div className=\"absolute left-1/2 top-1/2 flex -translate-x-1/2 -translate-y-1/2 flex-col items-center\">\n                <span className=\"relative inline-flex h-9 w-9 items-center justify-center rounded-full\" style={{ background: \"rgba(232,166,61,0.15)\", border: `1px solid ${C.amber}` }}>\n                  <span className=\"czw-ring absolute inset-0 rounded-full\" style={{ border: `1px solid ${C.amber}` }} />\n                  <Star size={16} style={{ color: C.amber }} fill={C.amber} aria-hidden=\"true\" />\n                </span>\n                <span className=\"mt-1 text-[9px] uppercase tracking-[0.2em]\" style={{ color: C.amber, ...mono }}>{tx.you}</span>\n              </div>\n              {/* contacts */}\n              {blips.map(({ c, x, y, angle }) => {\n                const color = c.ready ? C.amber : C.radar;\n                const on = target === c.username;\n                return (\n                  <button\n                    key={c.username}\n                    type=\"button\"\n                    onClick={() => setTarget(c.username)}\n                    aria-pressed={on}\n                    aria-label={`${c.username}${c.ready ? ` — ${tx.legendReady}` : \"\"}`}\n                    className=\"czw-blip group absolute z-[2] flex flex-col items-center\"\n                    style={{ left: `${x}%`, top: `${y}%`, animationDelay: `${(angle / 360) * SWEEP_S - SWEEP_S}s` }}\n                  >\n                    <span className=\"relative inline-flex h-3.5 w-3.5 items-center justify-center\">\n                      {c.ready && <span className=\"czw-ring absolute inset-0 rounded-full\" style={{ border: `1px solid ${color}` }} />}\n                      <span className=\"h-3 w-3 rounded-full\" style={{ background: color, boxShadow: `0 0 12px ${color}` }} />\n                      {on && <span className=\"czw-spin absolute -inset-3 rounded-full border border-dashed\" style={{ borderColor: RED }} />}\n                    </span>\n                    <span className=\"mt-1 whitespace-nowrap px-1 text-[10px] uppercase tracking-wider\" style={{ color: on ? C.paper : color, background: on ? \"rgba(220,38,38,0.85)\" : \"rgba(10,12,8,0.7)\", ...mono }}>{c.username}</span>\n                  </button>\n                );\n              })}\n              {contacts.length === 0 && (\n                <div className=\"absolute inset-x-0 bottom-[14%] text-center text-xs uppercase tracking-[0.2em]\" style={{ color: C.muted, ...mono }}>{tx.noContacts}</div>\n              )}\n            </div>\n          </Panel>\n\n          <div className=\"flex flex-col gap-6\">\n            {/* target lock */}\n            <Panel code=\"02\" icon={Crosshair} title={tx.target} accent={RED} delay={0.25}>\n              {!locked ? (\n                <p className=\"text-sm\" style={{ color: C.muted }}>{tx.noTarget}</p>\n              ) : (\n                <div key={locked.username} className=\"czw-in\">\n                  <div className=\"flex items-center gap-5\">\n                    <div className=\"relative shrink-0\">\n                      {avatar(locked.username, 92, RED)}\n                      <svg viewBox=\"0 0 100 100\" className=\"czw-spin pointer-events-none absolute -inset-3 h-[calc(100%+24px)] w-[calc(100%+24px)]\" aria-hidden=\"true\">\n                        <circle cx=\"50\" cy=\"50\" r=\"47\" fill=\"none\" stroke={RED} strokeWidth=\"1.2\" strokeDasharray=\"12 8\" />\n                      </svg>\n                      {[0, 90, 180, 270].map((d) => <span key={d} className=\"absolute left-1/2 top-1/2 h-3 w-[2px]\" style={{ background: RED, transform: `translate(-50%, -50%) rotate(${d}deg) translateY(-58px)` }} aria-hidden=\"true\" />)}\n                    </div>\n                    <div className=\"min-w-0\">\n                      <div className=\"text-[10px] uppercase tracking-[0.3em]\" style={{ color: RED, ...mono }}><span className=\"czw-blink\">▮</span> {tx.acquired}</div>\n                      <div className=\"cz-display mt-1 truncate text-4xl uppercase leading-none\" style={{ fontWeight: 700 }}>{locked.username}</div>\n                      <div className=\"mt-2 text-sm\" style={{ color: C.amber, fontWeight: 600 }}>{tierOf(locked.rating)[lang]} · <span style={{ color: C.paper }}>{locked.rating}</span> <span className=\"text-xs\" style={{ color: C.muted }}>{tx.rating}</span></div>\n                    </div>\n                  </div>\n                  <div className=\"mt-5 grid gap-px border text-sm\" style={{ background: C.line, borderColor: C.line }}>\n                    {\"ready\" in locked && locked.ready ? (\n                      <div className=\"flex flex-wrap items-center gap-2 px-4 py-3\" style={{ background: \"#0E110B\" }}>\n                        <span className=\"text-[10px] uppercase tracking-[0.2em]\" style={{ color: C.muted, ...mono }}>{tx.readyFor}</span>\n                        {locked.ready.modes.map((m) => <span key={m} className=\"border px-2 py-0.5 text-xs uppercase tracking-widest\" style={{ borderColor: C.amber, color: C.amber, fontWeight: 700 }}>{m}</span>)}\n                        <span className=\"ms-auto inline-flex items-center gap-1 text-xs\" style={{ color: C.muted }}><Clock size={12} aria-hidden=\"true\" />{tx.left(minsLeft(locked.ready.until))}</span>\n                      </div>\n                    ) : null}\n                    {\"page\" in locked && locked.page ? (\n                      <div className=\"flex items-center gap-2 px-4 py-3\" style={{ background: \"#0E110B\" }}>\n                        <span className=\"h-2 w-2 rounded-full\" style={{ background: C.radar }} />\n                        <span className=\"text-xs\" style={{ color: C.muted, ...mono }}>{tx.onPage} {locked.page}</span>\n                      </div>\n                    ) : null}\n                    {\"ready\" in locked && locked.ready?.note ? <div className=\"px-4 py-3 text-sm italic\" style={{ background: \"#0E110B\" }}>“{locked.ready.note}”</div> : null}\n                  </div>\n                  <div className=\"mt-5 flex flex-wrap gap-3\">\n                    {me && locked.username !== me.username && <ChallengeButton username={locked.username} defaultMode={(\"ready\" in locked && locked.ready?.modes[0]) || \"2v2\"} />}\n                    <Link href={`/profile/${locked.username}`} className=\"inline-flex min-h-[44px] items-center gap-2 border px-4 text-xs uppercase tracking-widest transition-colors hover:bg-[#171B10]\" style={{ borderColor: C.lineStrong, color: C.paper }}>{tx.profile}<ArrowUpRight size={14} className=\"rtl:-scale-x-100\" aria-hidden=\"true\" /></Link>\n                  </div>\n                </div>\n              )}\n            </Panel>\n\n            {/* deploy */}\n            {me && works && (\n              <Panel code=\"03\" icon={Shield} title={tx.deploy} accent={C.radar} delay={0.3}>\n                {mine ? (\n                  <div>\n                    <div className=\"flex items-center gap-3\">\n                      <span className=\"relative inline-flex h-3 w-3\"><span className=\"czw-ring absolute inset-0 rounded-full\" style={{ border: `1px solid ${C.radar}` }} /><span className=\"relative inline-block h-3 w-3 rounded-full\" style={{ background: C.radar }} /></span>\n                      <span className=\"flex-1 text-sm\" style={{ color: C.radar, fontWeight: 600 }}>{tx.deployedFor(minsLeft(mine.until))}</span>\n                    </div>\n                    <div className=\"mt-3 h-1.5 w-full\" style={{ background: C.line }} dir=\"ltr\">\n                      <div className=\"h-full transition-[width] duration-1000\" style={{ width: `${Math.min(100, ((Date.parse(mine.until) - now) / (Date.parse(mine.until) - Date.parse(mine.updated_at))) * 100)}%`, background: C.radar }} />\n                    </div>\n                    <button onClick={stopReady} disabled={busy === \"ready\"} className=\"mt-4 inline-flex min-h-[44px] items-center gap-2 border px-5 text-xs uppercase tracking-widest\" style={{ borderColor: C.lineStrong, color: C.paper }}>{tx.stop}</button>\n                  </div>\n                ) : (\n                  <>\n                    <p className=\"-mt-1 mb-4 text-xs\" style={{ color: C.muted }}>{tx.deploySub}</p>\n                    <div className=\"text-[10px] uppercase tracking-[0.25em]\" style={{ color: C.muted, ...mono }}>{tx.modes}</div>\n                    <div className=\"mt-2 grid grid-cols-5 gap-2\" role=\"group\" dir=\"ltr\">\n                      {PLAY_MODES.map((m) => {\n                        const on = modes.includes(m);\n                        return (\n                          <button key={m} type=\"button\" aria-pressed={on} onClick={() => setModes((x) => (on ? x.filter((y) => y !== m) : [...x, m]))} className=\"czw-plate relative flex min-h-[54px] flex-col items-center justify-center border\" style={{ background: on ? \"linear-gradient(180deg, rgba(232,166,61,0.25), rgba(232,166,61,0.08))\" : \"#0A0C08\", borderColor: on ? C.amber : C.lineStrong }}>\n                            <span className=\"cz-display text-lg uppercase leading-none\" style={{ color: on ? C.amber : C.paper, fontWeight: 700 }}>{m}</span>\n                            <span className=\"mt-1 h-1 w-6\" style={{ background: on ? C.amber : C.line }} />\n                          </button>\n                        );\n                      })}\n                    </div>\n                    <div className=\"mt-3 grid gap-2 sm:grid-cols-[1fr_auto]\">\n                      <input value={note} maxLength={120} onChange={(e) => setNote(e.target.value)} placeholder={tx.notePh} aria-label={tx.notePh} className=\"min-h-[44px] w-full border border-[#3A4029] bg-[#0A0C08] px-3 text-sm text-[#EDEAE0] focus:border-[#E8A63D]\" />\n                      <select value={minutes} onChange={(e) => setMinutes(Number(e.target.value))} aria-label={tx.for} className=\"min-h-[44px] border border-[#3A4029] bg-[#0A0C08] px-3 text-sm text-[#EDEAE0]\">\n                        {DURATIONS.map((d) => <option key={d} value={d}>{tx.for} {tx.min(d)}</option>)}\n                      </select>\n                    </div>\n                    <div className=\"mt-4 flex flex-wrap items-center gap-3\">\n                      <label className=\"inline-flex min-h-[40px] flex-1 items-center gap-2 text-sm\"><input type=\"checkbox\" checked={postReady} onChange={(e) => setPostReady(e.target.checked)} style={{ accentColor: C.amber, width: 16, height: 16 }} />{tx.postDiscord}</label>\n                      <button onClick={goReady} disabled={busy === \"ready\" || modes.length === 0} className=\"relative inline-flex min-h-[52px] items-center gap-2 overflow-hidden px-7 text-sm uppercase tracking-[0.18em] disabled:opacity-50\" style={{ background: C.radar, color: C.void, fontWeight: 800, boxShadow: \"0 0 26px rgba(143,191,79,0.35)\" }}>\n                        {busy === \"ready\" ? <Loader2 size={16} className=\"animate-spin\" aria-hidden=\"true\" /> : <UserCheck size={16} aria-hidden=\"true\" />}{tx.goReady}\n                      </button>\n                    </div>\n                  </>\n                )}\n              </Panel>\n            )}\n          </div>\n        </div>\n\n        {/* ===== transmissions + units ===== */}\n        <div className=\"mt-6 grid items-start gap-6 lg:grid-cols-2\">\n          {me && (\n            <Panel code=\"04\" icon={Radio} title={tx.transmissions} accent={RED} delay={0.35} right={incoming.length ? <span className=\"px-2 py-0.5 text-xs text-white\" style={{ background: RED, fontWeight: 800, ...mono }}>{incoming.length}</span> : null}>\n              {incoming.length === 0 && recentAccepted.length === 0 ? (\n                <p className=\"text-sm\" style={{ color: C.muted }}>{tx.noTransmissions}</p>\n              ) : (\n                <ul className=\"flex flex-col gap-3\">\n                  {incoming.map((c) => (\n                    <li key={c.id} className=\"czw-in relative overflow-hidden border p-4\" style={{ borderColor: \"rgba(220,38,38,0.6)\", background: \"linear-gradient(120deg, rgba(220,38,38,0.12), #0A0C08 65%)\" }}>\n                      <span aria-hidden=\"true\" className=\"czw-scan pointer-events-none absolute inset-x-0 top-0 h-full\" style={{ background: \"linear-gradient(180deg, transparent, rgba(220,38,38,0.10), transparent)\" }} />\n                      <div className=\"relative flex flex-wrap items-center gap-4\">\n                        {avatar(c.from_username, 46, RED)}\n                        <div className=\"min-w-0 flex-1\">\n                          <div className=\"text-[10px] uppercase tracking-[0.25em]\" style={{ color: LOSS, ...mono }}>⚔ {ago(c.created_at)}</div>\n                          <div className=\"text-base\"><Link href={`/profile/${c.from_username}`} className=\"hover:underline\" style={{ fontWeight: 700 }}>{c.from_username}</Link> <span className=\"cz-display ms-1 text-xl uppercase\" style={{ color: C.amber, fontWeight: 700 }}>{c.mode}</span></div>\n                          {c.message && <div className=\"text-sm italic\" style={{ color: C.paper }}>“{c.message}”</div>}\n                        </div>\n                        <div className=\"flex w-full gap-2 sm:w-auto [&>button]:flex-1 sm:[&>button]:flex-none\">\n                          <button onClick={() => respond(c, false)} disabled={busy === c.id} className=\"inline-flex min-h-[42px] items-center gap-1.5 border px-3 text-xs uppercase tracking-widest disabled:opacity-50\" style={{ borderColor: \"rgba(248,113,113,0.6)\", color: LOSS }}><X size={14} aria-hidden=\"true\" />{tx.decline}</button>\n                          <button onClick={() => respond(c, true)} disabled={busy === c.id} className=\"inline-flex min-h-[42px] items-center gap-1.5 px-4 text-xs uppercase tracking-widest disabled:opacity-50\" style={{ background: C.radar, color: C.void, fontWeight: 800 }}>{busy === c.id ? <Loader2 size={14} className=\"animate-spin\" aria-hidden=\"true\" /> : <Check size={14} aria-hidden=\"true\" />}{tx.accept}</button>\n                        </div>\n                      </div>\n                    </li>\n                  ))}\n                  {recentAccepted.map((c) => (\n                    <li key={c.id} className=\"flex flex-wrap items-center gap-3 border px-4 py-2.5 text-sm\" style={{ borderColor: C.line, background: \"#0A0C08\" }}>\n                      <Check size={15} style={{ color: C.radar }} aria-hidden=\"true\" />\n                      <span className=\"flex-1\">{c.from_username} · {c.mode.toUpperCase()} · <span style={{ color: C.radar }}>{tx.accepted}</span></span>\n                      <Link href={`/report?challenge=${c.id}`} className=\"text-xs uppercase tracking-widest\" style={{ color: C.amber }}>{tx.report}</Link>\n                    </li>\n                  ))}\n                </ul>\n              )}\n            </Panel>\n          )}\n\n          <Panel code=\"05\" icon={UserCheck} title={tx.units} accent={C.amber} delay={0.4} className={me ? \"\" : \"lg:col-span-2\"}>\n            {ready.length === 0 ? (\n              <p className=\"text-sm\" style={{ color: C.muted }}>{tx.noUnits}</p>\n            ) : (\n              <ul className=\"grid gap-3 sm:grid-cols-2\">\n                {ready.map((r) => {\n                  const total = Math.max(1, Date.parse(r.until) - Date.parse(r.updated_at));\n                  const pct = Math.max(0, Math.min(100, ((Date.parse(r.until) - now) / total) * 100));\n                  const rating = people[r.username]?.rating ?? 1000;\n                  return (\n                    <li key={r.user_id} className=\"czw-tag relative border p-4\" style={{ borderColor: C.line, background: \"linear-gradient(160deg, #161A11, #0A0C08)\", borderRadius: \"14px 4px 14px 4px\" }}>\n                      <span aria-hidden=\"true\" className=\"absolute end-3 top-3 h-2.5 w-2.5 rounded-full\" style={{ background: \"#0A0C08\", border: `1px solid ${C.lineStrong}` }} />\n                      <div className=\"flex items-center gap-3\">\n                        {avatar(r.username, 44, C.amber)}\n                        <div className=\"min-w-0\">\n                          <button type=\"button\" onClick={() => setTarget(r.username)} className=\"cz-display block truncate text-xl uppercase leading-none hover:underline\" style={{ fontWeight: 700 }}>{r.username}</button>\n                          <div className=\"mt-1 text-[11px] uppercase tracking-[0.15em]\" style={{ color: C.amber, ...mono }}>{tierOf(rating)[lang]} · {rating}</div>\n                        </div>\n                      </div>\n                      <div className=\"mt-3 flex flex-wrap gap-1\">{r.modes.map((m) => <span key={m} className=\"border px-1.5 py-px text-[11px] uppercase tracking-widest\" style={{ borderColor: C.amberDim, color: C.amber }}>{m}</span>)}</div>\n                      {r.note && <div className=\"mt-2 text-xs italic\" style={{ color: C.muted }}>“{r.note}”</div>}\n                      <div className=\"mt-3 flex items-center gap-2\">\n                        <div className=\"h-1 flex-1\" style={{ background: C.line }} dir=\"ltr\"><div className=\"h-full\" style={{ width: `${pct}%`, background: pct < 20 ? RED : C.amber, transition: \"width 1s linear\" }} /></div>\n                        <span className=\"text-[10px] tabular-nums\" style={{ color: C.muted, ...mono }}>{tx.left(minsLeft(r.until))}</span>\n                      </div>\n                      {me && r.user_id !== me.id && <div className=\"mt-3\"><ChallengeButton compact username={r.username} defaultMode={r.modes[0] ?? \"2v2\"} /></div>}\n                    </li>\n                  );\n                })}\n              </ul>\n            )}\n          </Panel>\n        </div>\n\n        {/* ===== comms row ===== */}\n        {me && (\n          <div className=\"mt-6 grid items-start gap-6 lg:grid-cols-3\">\n            <Panel code=\"06\" icon={Search} title={tx.manual} delay={0.45}>\n              <datalist id=\"play-names\">{names.filter((n) => n !== me.username).map((n) => <option key={n} value={n} />)}</datalist>\n              <div className=\"flex gap-2\">\n                <input list=\"play-names\" value={find} onChange={(e) => setFind(e.target.value)} onKeyDown={(e) => { if (e.key === \"Enter\" && findMatch) setTarget(findMatch); }} placeholder={tx.manualPh} className=\"min-h-[44px] min-w-0 flex-1 border border-[#3A4029] bg-[#0A0C08] px-3 text-sm text-[#EDEAE0] focus:border-[#E8A63D]\" />\n                {findMatch && <button type=\"button\" onClick={() => setTarget(findMatch)} aria-label={tx.target} className=\"inline-flex min-h-[44px] w-11 items-center justify-center border\" style={{ borderColor: RED, color: RED }}><Crosshair size={17} aria-hidden=\"true\" /></button>}\n              </div>\n              {findMatch && <div className=\"mt-3\"><ChallengeButton username={findMatch} /></div>}\n            </Panel>\n\n            {works && (\n              <Panel code=\"07\" icon={BellRing} title={tx.radio} delay={0.5}>\n                {push === \"unsupported\" ? (\n                  <p className=\"text-sm\" style={{ color: C.muted }}>{tx.radioNoSupport}</p>\n                ) : (\n                  <div className=\"flex flex-col gap-3\">\n                    <span className=\"text-sm\" style={{ color: push === \"on\" ? C.radar : C.muted }}>{push === \"on\" ? tx.radioOn : tx.radioOff}</span>\n                    <button onClick={togglePush} disabled={push === \"loading\"} className=\"inline-flex min-h-[44px] w-fit items-center gap-2 px-5 text-xs uppercase tracking-widest disabled:opacity-50\" style={push === \"on\" ? { border: `1px solid ${C.lineStrong}`, color: C.paper } : { background: C.amber, color: C.void, fontWeight: 800 }}>\n                      {push === \"loading\" ? <Loader2 size={15} className=\"animate-spin\" aria-hidden=\"true\" /> : push === \"on\" ? <BellOff size={15} aria-hidden=\"true\" /> : <BellRing size={15} aria-hidden=\"true\" />}\n                      {push === \"on\" ? tx.turnOff : tx.turnOn}\n                    </button>\n                  </div>\n                )}\n              </Panel>\n            )}\n\n            <Panel code=\"08\" icon={Send} title={tx.dispatched} delay={0.55}>\n              {outgoing.length === 0 ? (\n                <p className=\"text-sm\" style={{ color: C.muted }}>{tx.noTransmissions}</p>\n              ) : (\n                <ul className=\"flex flex-col gap-px border\" style={{ background: C.line, borderColor: C.line }}>\n                  {outgoing.map((c) => {\n                    const expired = c.status === \"pending\" && Date.parse(c.expires_at) <= now;\n                    const color = c.status === \"accepted\" ? C.radar : c.status === \"pending\" && !expired ? C.amber : C.muted;\n                    return (\n                      <li key={c.id} className=\"flex flex-wrap items-center gap-x-3 gap-y-1 px-3 py-2.5 text-sm\" style={{ background: \"#0A0C08\", borderInlineStart: `3px solid ${color}` }}>\n                        <span className=\"w-full min-w-0 truncate\"><b>{c.to_username}</b> <span style={{ color: C.muted, ...mono }}>· {c.mode.toUpperCase()} · {ago(c.created_at)}</span></span>\n                        <span className=\"me-auto text-[10px] uppercase tracking-widest\" style={{ color, fontWeight: 700, ...mono }}>{expired ? tx.expired : tx.st[c.status]}</span>\n                        {c.status === \"pending\" && !expired && <button onClick={() => cancel(c)} disabled={busy === c.id} className=\"text-[11px] uppercase tracking-widest underline-offset-2 hover:underline\" style={{ color: C.muted }}>{tx.cancel}</button>}\n                        {c.status === \"accepted\" && <Link href={`/report?challenge=${c.id}`} className=\"text-[11px] uppercase tracking-widest\" style={{ color: C.amber }}>{tx.report}</Link>}\n                      </li>\n                    );\n                  })}\n                </ul>\n              )}\n            </Panel>\n          </div>\n        )}\n      </div>\n    </main>\n  );\n}\n", "sig": "export default function PlayView", "drop": [], "skipIf": []}];
const SUFFIX = '.reportv2bak', NEWMARK = '.reportv2new';
const g = (s) => '\x1b[32m' + s + '\x1b[0m', r = (s) => '\x1b[31m' + s + '\x1b[0m';
if (!fs.existsSync(P('package.json'))) { console.error(r('Run this from the commander-hub folder (next to package.json).')); process.exit(1); }

if (process.argv.includes('--undo')) {
  for (const f of FILES) {
    if (fs.existsSync(P(f.path) + SUFFIX)) { fs.copyFileSync(P(f.path) + SUFFIX, P(f.path)); fs.unlinkSync(P(f.path) + SUFFIX); console.log(g('✔') + ' restored ' + f.path); }
    else if (fs.existsSync(P(f.path) + NEWMARK)) { fs.unlinkSync(P(f.path)); fs.unlinkSync(P(f.path) + NEWMARK); console.log(g('✔') + ' removed ' + f.path); }
  }
  console.log('\nClean restart to see the previous version.');
  process.exit(0);
}

// 1) check everything before writing anything
const fns = (s) => [...s.matchAll(/(?:async\s+)?function\s+([A-Za-z0-9_]+)\s*\(/g)].map((m) => m[1]);
const tables = (s) => [...s.matchAll(/\.from\(\s*["'`]([A-Za-z0-9_]+)["'`]/g)].map((m) => m[1]);
const imports = (s) => [...s.matchAll(/from\s+["']([^"']+)["']/g)].map((m) => m[1]);
const allNew = FILES.map((f) => f.src).join('\n');
const newSets = { fns: new Set(fns(allNew)), tables: new Set(tables(allNew)), imports: new Set(imports(allNew)) };
const problems = [];
// Earlier installers this one builds on must already be installed
{
  const missing = FILES.filter((f) => f.require && !fs.existsSync(P(f.path)));
  if (missing.length) {
    for (const f of missing) console.log('\x1b[31m✘\x1b[0m ' + f.path + ' is missing — run ' + f.require + ' first.');
    console.log('\nNothing was changed.');
    process.exit(1);
  }
}
// Files to remove (known to break the build) are backed up first and restored by --undo
// Files that would clash with something you already have are skipped, not forced
for (const f of FILES) {
  const clash = (f.skipIf || []).find((p) => fs.existsSync(P(p)));
  if (clash) { f.skip = clash; }
}
for (const f of FILES) {
  if (f.skip || f.remove || f.require) continue;
  if (!f.sig) continue; // brand-new file
  if (!fs.existsSync(P(f.path))) { problems.push(f.path + ' not found'); continue; }
  const cur = fs.readFileSync(P(f.path), 'utf8');
  if (f.enc !== 'base64' && cur === f.src) continue;
  if (!cur.includes(f.sig)) { problems.push(f.path + ' has unexpected contents (missing "' + f.sig + '")'); continue; }
  for (const x of fns(cur)) if (!newSets.fns.has(x)) problems.push(f.path + ': function ' + x + ' would be lost');
  for (const x of tables(cur)) if (!newSets.tables.has(x)) problems.push(f.path + ': table "' + x + '" would no longer be used');
  for (const x of imports(cur)) if (!newSets.imports.has(x) && !(f.drop || []).includes(x)) problems.push(f.path + ': import "' + x + '" would be lost');
}
if (problems.length) {
  console.error(r('Nothing was changed:'));
  problems.forEach((p) => console.error('  - ' + p));
  console.error('Send this list to Claude.');
  process.exit(1);
}

// 2) back up and write
let ok = true;
for (const f of FILES) {
  if (f.require) continue;
  if (f.skip) { console.log('\x1b[33m!\x1b[0m skipped ' + f.path + ' (you already have ' + f.skip + ')'); continue; }
  if (f.remove) {
    if (fs.existsSync(P(f.path))) {
      if (!fs.existsSync(P(f.path) + SUFFIX)) fs.copyFileSync(P(f.path), P(f.path) + SUFFIX);
      fs.unlinkSync(P(f.path));
      console.log(g('✔') + ' removed ' + f.path + ' (it breaks the production build; backup kept)');
    }
    continue;
  }
  fs.mkdirSync(path.dirname(P(f.path)), { recursive: true });
  const content = f.enc === 'base64' ? Buffer.from(f.src, 'base64') : Buffer.from(f.src, 'utf8');
  const same = (p) => fs.existsSync(p) && Buffer.compare(fs.readFileSync(p), content) === 0;
  const existed = fs.existsSync(P(f.path));
  if (existed && !fs.existsSync(P(f.path) + SUFFIX) && !fs.existsSync(P(f.path) + NEWMARK) && !same(P(f.path))) fs.copyFileSync(P(f.path), P(f.path) + SUFFIX);
  if (!existed) fs.writeFileSync(P(f.path) + NEWMARK, '');
  fs.writeFileSync(P(f.path), content);
  const good = same(P(f.path));
  ok = ok && good;
  console.log((good ? g('✔') : r('✘')) + ' ' + f.path + (existed ? '' : '  (new)'));
}
if (!ok) { console.error(r('\nA file did not verify. Run with --undo.')); process.exit(1); }
console.log(g('\nInstalled.') + ' Now do a clean restart:');
console.log('  Get-Process node -ErrorAction SilentlyContinue | Stop-Process -Force');
console.log('  Remove-Item -Recurse -Force .next');
console.log('  npm run dev');
console.log('Then npm run build and push. Undo: node install-report-v2.js --undo\n');
